INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3025', 'spa', 'Lagar o cuba de vino; la artesa donde se pisan las uvas, usada literalmente y como símbolo del juicio divino.', 'Un λήνος es una artesa o cuba para prensar uvas, elemento habitual de la agricultura mediterránea que se convirtió en una de las imágenes más vívidas de la ira divina en las Escrituras. Jesús lo menciona en la parábola de los labradores malvados (Mt 21:33), donde el dueño instala un lagar como parte de una viña en funcionamiento. Apocalipsis lo transforma en imaginería apocalíptica: «el gran lagar de la ira de Dios» es pisado hasta que la sangre sube hasta los frenos de los caballos (Ap 14:19-20; 19:15). El término transmite tanto su sentido agrícola concreto como la furia escatológica del juicio final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3026', 'spa', 'desatino, disparate, palabrería vacía e indigna de atención seria', 'Este sustantivo descarta algo como charla inútil, disparate sin sentido o palabras vacías que no merecen atención seria. En el uso clásico se aplicaba a asuntos triviales, discursos necios o cosas consideradas inservibles. En Lucas 24:11, los apóstoles consideraron inicialmente el relato de las mujeres sobre la resurrección como un desatino, reflejando tanto los prejuicios de la época sobre el testimonio femenino como la pura incredibilidad de la afirmación. Este momento revela las barreras culturales que las primeras testigos tuvieron que superar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3027', 'spa', 'Ladrón, bandido, salteador; quien se apodera de bienes ajenos mediante la violencia, a diferencia del simple ratero. λῃστής es un saqueador violento q', 'Ladrón, bandido, salteador; quien se apodera de bienes ajenos mediante la violencia, a diferencia del simple ratero. λῃστής es un saqueador violento que toma por la fuerza, la emboscada o la intimidación armada, en contraste con el κλέπτης que hurta con sigilo. El griego clásico aplicaba el término a piratas y combatientes irregulares; el Nuevo Testamento conserva esta connotación de agresión abierta y descarada. Jesús cita a Jeremías cuando acusa a los mercaderes del templo de convertir la casa de Dios en «cueva de ladrones» (Mt 21:13; Mc 11:17). Los dos hombres crucificados junto a Jesús son llamados λῃσταί (Mt 27:38), posiblemente indicando insurrectos. La parábola del Buen Samaritano gira en torno a un hombre que cayó en manos de λῃσταί en el camino a Jericó (Lc 10:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3028', 'spa', 'recepción, acto de recibir o aceptar algo, especialmente en contextos comerciales o de intercambio', 'Este sustantivo designa el acto de recibir o aceptar algo, ya sean ofrendas, pagos u otros tipos de transferencias. En contextos comerciales, se refería a recibos o ingresos. Pablo lo emplea en Filipenses 4:15 dentro de una metáfora contable, señalando que ninguna otra iglesia compartió con él en materia de dar y recibir excepto los filipenses. Este lenguaje financiero enmarca teológicamente el apoyo material como una verdadera asociación en el ministerio del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3029', 'spa', 'Muy, extremadamente, en gran manera — adverbio intensivo que amplifica el grado de una acción o cualidad. λίαν es un adverbio intensivo directo que si', 'Muy, extremadamente, en gran manera — adverbio intensivo que amplifica el grado de una acción o cualidad. λίαν es un adverbio intensivo directo que significa «muy» o «en gran manera», usado 12 veces en el Nuevo Testamento para amplificar verbos y adjetivos. Con frecuencia tiñe las escenas de emoción intensificada: Herodes se turba λίαν al saber del rey recién nacido (Mt 2:16), los endemoniados son λίαν feroces (Mt 8:28), y Pilato se asombra λίαν ante el silencio de Jesús (Mt 27:14). Marcos lo emplea para enfatizar lo temprano de la mañana de la resurrección — λίαν πρωΐ, «muy de mañana» (Mc 16:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3032', 'spa', 'liberto, esclavo manumitido que ha obtenido su libertad', 'Este préstamo del latín designa a un esclavo liberado, alguien que había estado en esclavitud pero que obtuvo o compró su manumisión. En Hechos 6:9 identifica una sinagoga de los Libertinos (Libertos) en Jerusalén, probablemente compuesta por esclavos judíos liberados o sus descendientes provenientes de diversas regiones. Tales sinagogas organizadas según líneas étnicas o sociales eran comunes en el período del Segundo Templo, reflejando la compleja realidad social del mundo romano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3033', 'spa', 'Libia, región del norte de África al oeste de Egipto', 'Libia designaba la región norteafricana al oeste de Egipto, particularmente las zonas costeras conocidas por el mundo grecorromano. En la geografía antigua, el término a menudo se refería de manera amplia al continente africano más allá de Egipto. Hechos 2:10 menciona a judíos de las partes de Libia cercanas a Cirene entre los presentes en Pentecostés, representando la extensa diáspora judía que se había establecido en importantes centros urbanos del norte de África.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3034', 'spa', 'Apedrear; arrojar piedras como forma de castigo o ataque violento, especialmente por presunta blasfemia.', 'Significa apedrear o lanzar piedras contra alguien, una forma de ejecución o violencia colectiva profundamente arraigada en la tradición legal mosaica. En el Nuevo Testamento, λιθάζω aparece casi exclusivamente en contextos donde Jesús y sus seguidores enfrentan hostilidad mortal. Los fariseos invocan el mandato mosaico de apedrear a las adúlteras (Jn 8:5), y los adversarios judíos de Jesús intentan apedrearlo por supuesta blasfemia en varias ocasiones (Jn 10:31-33; 11:8). Pablo fue efectivamente apedreado y dado por muerto en Listra (Hch 14:19; 2 Co 11:25). Hebreos 11:37 recuerda la lapidación de los fieles a lo largo de la historia de Israel. El español «apedrear» (de piedra) y el francés «lapider» transmiten el carácter específicamente judicial o tumultuario de este acto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3035', 'spa', 'De piedra; hecho o construido con piedra como material', 'Este adjetivo describe objetos fabricados con piedra en lugar de otros materiales. En el mundo antiguo, los recipientes de piedra se valoraban por su pureza ritual, ya que no contraían impureza como la cerámica. Juan 2:6 menciona seis tinajas de piedra usadas para la purificación judía, escenario de la primera señal de Jesús al convertir agua en vino. Pablo contrasta las tablas de piedra de la ley mosaica con los corazones de carne donde el Espíritu escribe (2 Corintios 3:3), distinguiendo la ley externa de la antigua alianza frente a la transformación interna de la nueva. Apocalipsis 9:20 condena a quienes adoran ídolos de piedra incapaces de ver, oír o caminar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3036', 'spa', 'Apedrear, lanzar piedras como ejecución judicial o violencia colectiva; término bíblico estándar para la muerte por lapidación.', 'λιθοβολέω es el verbo compuesto para apedrear, formado por λίθος (piedra) y βάλλω (lanzar). Aparece exclusivamente en contextos de violencia letal o casi letal. Jesús se lamenta sobre Jerusalén como la ciudad que ''apedrea a los que le son enviados'' (Mt 23:37; Lc 13:34), convirtiendo esta palabra en un estribillo amargo de rechazo profético. En Hechos 7:58-59 narra la ejecución de Esteban con detalle estremecedor. El español ''apedrear'' (de ''piedra'') refleja con transparencia el compuesto griego, conservando la conexión visceral entre la roca y el acto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3037', 'spa', 'Piedra, roca -- trozo de roca natural, labrada para construcción, preciosa o empleada figuradamente para dureza y rechazo.', 'Λίθος es el término griego común para piedra, y abarca un rango material y figurado excepcionalmente amplio en el Nuevo Testamento. En sentido literal designa rocas naturales (Mt 3:9, Dios puede levantar hijos de las piedras), sillares de construcción (Mr 13:1-2, las enormes piedras del templo de Herodes), piedras de molino (Lc 17:2) y piedras preciosas (Ap 21:19). Figuradamente, se convierte en una de las imágenes cristológicas más ricas del NT: Cristo como la piedra que desecharon los edificadores y que vino a ser cabeza del ángulo (Mt 21:42, citando Sal 118:22), piedra de tropiezo (Ro 9:33; 1 P 2:8) y piedra viva sobre la cual se edifican los creyentes (1 P 2:4-5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3038', 'spa', 'enlosado de piedra, pavimento de mosaico o piso teselado', 'Este término describe un pavimento hecho de piedras encajadas, particularmente un elaborado trabajo de mosaico o teselado. En Juan 19:13 designa el lugar llamado «el Enlosado» (en arameo, Gabatá), donde Pilato se sentó en el tribunal para pronunciar sentencia sobre Jesús. La evidencia arqueológica sugiere que se trataba de un patio pavimentado en el pretorio. Este detalle arquitectónico preciso marca el escenario del momento culminante del juicio de Jesús ante la autoridad romana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3040', 'spa', 'Puerto, refugio costero; zona resguardada donde los barcos pueden anclar con seguridad', 'Un puerto o refugio costero ofrecía protección esencial a las embarcaciones antiguas, resguardándolas de las tormentas y proporcionando un lugar seguro para anclar. En una época en que la navegación era peligrosa y los naufragios frecuentes, encontrar un buen puerto podía significar la diferencia entre la vida y la muerte. Las tres apariciones de este término en el Nuevo Testamento se encuentran en Hechos 27, durante la azarosa travesía de Pablo hacia Roma. Buenos Puertos (27:8) resultó inadecuado para invernar, lo que llevó a la decisión de navegar hacia Fenice, un puerto mejor en Creta (27:12). Esa fatídica decisión desencadenó la tempestad y el naufragio que dominan el capítulo, aunque Dios preservó a todos los que iban a bordo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3041', 'spa', 'Lago — un cuerpo de agua estancada; el lago de Genesaret (Mar de Galilea) y el lago de fuego escatológico. El sustantivo λίμνη (limne) significa ''lago', 'Lago — un cuerpo de agua estancada; el lago de Genesaret (Mar de Galilea) y el lago de fuego escatológico. El sustantivo λίμνη (limne) significa ''lago'' y aparece en dos registros marcadamente distintos. Solo Lucas entre los evangelistas lo usa para referirse al Mar de Galilea, llamándolo ''el lago de Genesaret'' (Lc 5:1-2) y simplemente ''el lago'' durante la tormenta y el episodio del endemoniado gadareno (Lc 8:22-33), prefiriendo la precisión geográfica de λίμνη sobre el semítico ''mar'' (θάλασσα). En Apocalipsis, la palabra adquiere una dimensión escatológica aterradora como el ''lago de fuego'', el destino final de la bestia, el falso profeta, la muerte, el Hades y todos aquellos cuyos nombres no están escritos en el libro de la vida (Ap 19:20; 20:10, 14-15; 21:8). El español ''lago'' y el francés ''lac'' sirven para ambos sentidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3042', 'spa', 'Hambre, hambruna — escasez severa de alimentos, ya sea como catástrofe regional o como privación personal. λιμός abarca todo el espectro de la privaci', 'Hambre, hambruna — escasez severa de alimentos, ya sea como catástrofe regional o como privación personal. λιμός abarca todo el espectro de la privación alimentaria, desde la hambruna a gran escala que devasta regiones enteras hasta el hambre punzante de un individuo. Sus 12 apariciones en el NT figuran en catálogos apocalípticos de tribulación (Mt 24:7; Mc 13:8; Ap 6:8; 18:8), relatos históricos de hambrunas específicas (Lc 4:25, la sequía en tiempos de Elías; Hch 11:28, la hambruna bajo Claudio), y el hambre profundamente personal del hijo pródigo (Lc 15:14, 17). Pablo incluye λιμός entre las penalidades que ha soportado por Cristo (2 Co 11:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3044', 'spa', 'Lino, cristiano en Roma saludado por Pablo', 'Lino fue un creyente cristiano en Roma mencionado junto a Claudia y otros en los saludos de Pablo en 2 Timoteo. La tradición eclesiástica temprana lo identificó como uno de los primeros obispos de Roma, aunque esta conexión es incierta. El nombre era común en el mundo grecorromano, originalmente asociado con un mítico cantor de la leyenda griega. Su mención por Pablo lo sitúa dentro de la comunidad cristiana de la era apostólica en la capital imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3045', 'spa', 'cosas lujosas, costosas y suntuosas', 'Este adjetivo describe aquello que es rico, lujoso o caracterizado por un refinamiento costoso. Originalmente aplicado a objetos aceitosos o brillantes, pasó a denotar una vida suntuosa y bienes de alto precio. En Apocalipsis 18:14, describe las cosas lujosas y espléndidas que Babilonia anhelaba, ahora perdidas para siempre en su juicio, subrayando la naturaleza efímera de la riqueza mundana y la vanidad de la opulencia terrenal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3047', 'spa', 'viento o dirección del suroeste', 'Este sustantivo designa el viento del suroeste, uno de los vientos direccionales con nombre propio en la navegación mediterránea antigua. En Hechos 27:12, aparece en una descripción náutica del puerto de Buenos Puertos, que daba hacia el suroeste y el noroeste. Los marineros antiguos distinguían los vientos según su dirección, y este término especificaba el cálido viento del suroeste, frecuente en el Mediterráneo, fundamental para la planificación de rutas marítimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3049', 'spa', 'Calcular, contar, considerar; acreditar a una cuenta, evaluar mentalmente o razonar con detenimiento.', 'Calcular, contar, considerar; acreditar a una cuenta, evaluar mentalmente o razonar con detenimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3051', 'spa', 'Oráculo; declaración divina o conjunto de revelaciones de Dios, especialmente las confiadas a Israel.', 'Λόγιον (diminutivo de λόγος) designa un dicho u oráculo divino — una palabra que lleva el peso de la voz misma de Dios. En el NT aparece siempre en plural (λόγια), refiriéndose al cuerpo de revelaciones divinas. Esteban habla de Moisés recibiendo «oráculos vivientes» en el Sinaí (Hch 7:38); Pablo afirma que a los judíos les fueron confiados «los oráculos de Dios» (Ro 3:2). El autor de Hebreos reprende a quienes aún necesitan instrucción en los oráculos elementales (Heb 5:12), y Pedro exhorta a que quien hable lo haga como quien transmite los oráculos de Dios (1 Pe 4:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3052', 'spa', 'elocuente, erudito, hábil en el discurso', 'Este adjetivo describe a alguien dotado para el discurso, el saber o la retórica: elocuente y persuasivo en su comunicación. En el uso clásico, denotaba tanto erudición académica como destreza oratoria. Hechos 18:24 lo aplica a Apolos, un judío alejandrino que era a la vez instruido en las Escrituras y poderoso en la palabra, aunque inicialmente solo conocía el bautismo de Juan. Su ejemplo muestra que la elocuencia debe ir acompañada de un conocimiento pleno del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3054', 'spa', 'disputar sobre palabras, enzarzarse en contiendas verbales', 'Este verbo significa pelear o contender por palabras, participando en disputas contenciosas sobre terminología o semántica en lugar de cuestiones de fondo. Sugiere una argumentación fútil que genera más calor que luz. En 2 Timoteo 2:14, Pablo advierte contra esta práctica, señalando que no aprovecha para nada y conduce a la ruina de los oyentes. Es una exhortación directa a evitar polémicas estériles que desvían de la verdad del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3055', 'spa', 'contiendas de palabras, disputas verbales', 'Este sustantivo denota querellas o controversias centradas en palabras y semántica en vez de en la verdad sustancial. Describe la actividad de la logomaquia: pelear por terminología, definiciones o formulaciones verbales de maneras que oscurecen en lugar de aclarar. En 1 Timoteo 6:4, Pablo asocia tales contiendas de palabras con el afán enfermizo por controversias propio de los falsos maestros, vinculándolas con la envidia, la disensión y las sospechas malignas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3056', 'spa', 'Palabra, mensaje o discurso; también cuenta/rendición, el Logos divino y razón/causa: la expresión más plena de comunicación racional.', 'Pocas palabras griegas portan tanta carga teológica como λόγος. En su nivel cotidiano significa simplemente «palabra» o «mensaje», y esto explica la gran mayoría de sus 332 apariciones neotestamentarias: desde las parábolas de Jesús sobre la «palabra» sembrada como semilla (Mt 13:19-23) hasta la «palabra de la cruz» de Pablo (1 Co 1:18). Pero el Prólogo joánico lo eleva a título cristológico: «En el principio era el Λόγος» (Jn 1:1), donde el español se divide entre Palabra y el latinismo Verbo, y algunas tradiciones conservan el préstamo Lógos. Por otra parte, el sentido contable —«ajustar cuentas» (Mt 18:23; 25:19)— preserva la conexión del vocablo con λέγω en su acepción de «contar, calcular», una dimensión casi invisible en el uso moderno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3058', 'spa', 'Injuriar, ultrajar verbalmente; insultar con lenguaje áspero y despectivo.', 'Λοιδορέω describe el acto de lanzar insultos y ultrajes verbales contra alguien — no una crítica casual, sino un vituperio agudo y despectivo. En el NT aparece en contextos de hostilidad injusta: los fariseos injurian al ciego de nacimiento por seguir a Jesús (Jn 9:28), Pablo es amonestado por ultrajar al sumo sacerdote (Hch 23:4), y tanto Pablo como Cristo soportan injurias sin represalia (1 Co 4:12; 1 Pe 2:23). La respuesta de Cristo — siendo injuriado, no injuriaba a su vez — se convirtió en paradigma de la no represalia cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3059', 'spa', 'Insulto, injuria verbal; discurso difamatorio o ultrajante dirigido a deshonrar a otro', 'Esta palabra describe un lenguaje verbalmente abusivo: injurias, insultos y calumnias diseñados para avergonzar y deshonrar a otra persona. Va más allá de la simple crítica; es un ataque verbal malintencionado. Pablo advierte a Timoteo sobre viudas jóvenes que podrían dar al adversario «ocasión de reproche» (1 Timoteo 5:14), es decir, motivos para insultar a la iglesia. Pedro instruye dos veces a los creyentes a no devolver insulto por insulto (1 Pedro 3:9), sino a bendecir a quienes los ultrajan. Esta respuesta radical refleja el ejemplo de Jesús, quien al ser injuriado no respondió con injurias (1 Pedro 2:23). El hablar del cristiano debe reflejar gracia, no represalia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3062', 'spa', 'Los restantes, los demas; adjetivo sustantivado que designa las personas o cosas que quedan de un grupo.', 'Los restantes, los demas; adjetivo sustantivado que designa las personas o cosas que quedan de un grupo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3063', 'spa', 'Finalmente, además (marcador discursivo); restante, lo demás (adjetivo); en adelante, de ahora en más (temporal). Formado sobre el adjetivo λοιπός («r', 'Finalmente, además (marcador discursivo); restante, lo demás (adjetivo); en adelante, de ahora en más (temporal). Formado sobre el adjetivo λοιπός («restante»), la forma neutra τὸ λοιπόν funciona como una de las palabras de transición predilectas de Pablo, señalando «finalmente» o «además» al pasar a las exhortaciones finales (Fil 3:1; 4:8; 2 Co 13:11; 1 Ts 4:1; 2 Ts 3:1). Sin embargo, conserva su fuerza adjetival en pasajes como Mt 26:45 y Mc 14:41, donde Jesús dice «dormid el tiempo restante», y en 1 Co 7:29, donde «el tiempo restante es corto». Un tercer uso, puramente temporal, aparece en 2 Ti 4:8: «en adelante me está reservada la corona de justicia».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3065', 'spa', 'Lucas; el médico y escritor del Evangelio, compañero de viaje de Pablo', 'Lucas, probablemente un creyente gentil (según se infiere de Colosenses 4:14, que lo distingue de «los de la circuncisión»), acompañó a Pablo durante varias etapas de sus viajes misioneros, como lo evidencian las secciones en primera persona plural del libro de Hechos. Pablo lo llama con afecto «el médico amado» (Colosenses 4:14), lo que sugiere tanto habilidad médica como cercanía personal. Cuando la mayoría había abandonado a Pablo durante su último encarcelamiento, «solo Lucas está conmigo» (2 Timoteo 4:11), testimonio de amistad fiel. La tradición le atribuye la autoría del Evangelio que lleva su nombre y del libro de Hechos, obras que destacan por su investigación histórica cuidadosa y su interés por los marginados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3068', 'spa', 'Lavar o bañar el cuerpo entero, a diferencia de lavar solo las manos o los pies.', 'Este verbo denota un lavado o baño completo del cuerpo, en contraste con νίπτω, que se refiere a lavar una parte específica como las manos o los pies. Jesús recurre a esta distinción en Jn 13:10: «El que se ha bañado (λελουμένος) solo necesita lavarse los pies». En Hechos, la palabra aparece en sentido literal: el cuerpo de Tabita es lavado tras su muerte (9:37) y el carcelero de Filipos lava las heridas de Pablo y Silas (16:33). Heb 10:22 espiritualiza la imagen: los creyentes se acercan a Dios «con el cuerpo lavado con agua pura». 2 Pe 2:22 lo usa de una cerda que vuelve a revolcarse tras haber sido lavada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3069', 'spa', 'Lida; ciudad de Judea situada en la llanura costera entre Jope y Jerusalén', 'Lida (la actual Lod en Israel) era una ciudad importante en el camino entre Jerusalén y la costa mediterránea, a unos 18 kilómetros al sureste de Jope. Tenía una población judía considerable en el siglo I. Hechos 9 relata la visita de Pedro durante su ministerio itinerante. Allí encontró a Eneas, un paralítico postrado en cama durante ocho años, y lo sanó en el nombre de Jesús. Como resultado, «todos los que habitaban en Lida y en Sarón se convirtieron al Señor» (Hechos 9:32-35). Desde Lida, Pedro fue llamado a la cercana Jope cuando murió Dorcas (9:38). La ciudad sirvió como centro estratégico para la expansión cristiana en la Judea costera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3071', 'spa', 'Licaonia, region interior en el centro-sur de Asia Menor', 'Licaonia era una región de meseta en el centro-sur de Asia Menor, habitada por un grupo étnico distintivo con su propio idioma. Entre sus ciudades importantes se encontraban Listra, Derbe e Iconio. Hechos 14:6 menciona que Pablo y Bernabé huyeron a las ciudades de Licaonia durante su primer viaje misionero, donde encontraron tanto hospitalidad como hostilidad en esta región fronteriza de diversidad cultural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3072', 'spa', 'en lengua licaónica, en el idioma de Licaonia', 'Este adverbio indica que alguien habla en el idioma licaonio, la lengua nativa de Licaonia, distinta del griego o el latín. Hechos 14:11 relata que, después de que Pablo sanó a un cojo en Listra, la multitud exclamó en licaonio que los dioses habían descendido en forma humana. Este detalle lingüístico revela la brecha cultural entre los apóstoles y la población local, y pone de manifiesto la diversidad de lenguas en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3073', 'spa', 'Licia, región costera en el suroeste de Asia Menor', 'Licia era una región montañosa y costera en el suroeste de Asia Menor, conocida por su cultura distintiva y su federación de ciudades-estado. La región incluía puertos importantes como Pátara y Mira. Hechos 27:5 menciona que la nave de Pablo navegó por el mar frente a Cilicia y Panfilia hasta llegar a Mira de Licia durante su travesía hacia Roma, un trayecto que resultaría especialmente peligroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3074', 'spa', 'λύκος (lykos) -- lobo; canino depredador usado literalmente del animal y figuradamente de personas peligrosas y engañosas', 'El lykos es el depredador por excelencia del mundo pastoral antiguo, el enemigo contra el cual el pastor debe estar en guardia. Jesús recurre a esta imagen profundamente familiar tanto literal como metafóricamente: los lobos vienen con piel de oveja como falsos profetas (Matt 7:15), y los discípulos son enviados como ovejas en medio de lobos (Matt 10:16; Luke 10:3). En John 10:12 el asalariado huye cuando el lobo ataca, en contraste con el Buen Pastor que da su vida por las ovejas. La imagen evoca la amenaza constante del engaño y la destrucción que acecha a la grey de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3075', 'spa', 'asolar, devastar, destruir violentamente', 'Este verbo describe una destrucción violenta o devastación, originalmente usado para el trabajo destructivo de los bataneros, pero extendido a cualquier daño ruinoso. En Hechos 8:3 caracteriza la persecución de Saulo contra la iglesia antes de su conversión: asolaba la iglesia, entrando casa por casa y arrastrando a hombres y mujeres para encarcelarlos. La intensidad del término subraya el celo persecutor de Saulo y hace aún más dramática su posterior transformación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3076', 'spa', 'Entristecer o causar afliccion; experimentar un dolor profundo o hacer que otro se entristezca.', 'Entristecer o causar afliccion; experimentar un dolor profundo o hacer que otro se entristezca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3077', 'spa', 'Tristeza, dolor o pena del corazón; angustia emocional profunda, frecuentemente contrastada con el gozo. λύπη cubre todo el espectro de la angustia in', 'Tristeza, dolor o pena del corazón; angustia emocional profunda, frecuentemente contrastada con el gozo. λύπη cubre todo el espectro de la angustia interior, desde el dolor agudo hasta la tristeza persistente. Su concentración más rica en el NT aparece en el discurso del Aposento Alto, donde Jesús dice a sus discípulos que su tristeza se convertirá en gozo, comparándola con los dolores de parto de una mujer (Jn 16:20-22). Pablo escribe de una tristeza según Dios que produce arrepentimiento (2 Co 7:10), distinguiéndola de la tristeza del mundo que conduce a la muerte. En Getsemaní, los discípulos duermen de λύπη (Lc 22:45).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3078', 'spa', 'Lisanias, tetrarca de Abilene en la cronología de Lucas', 'Lisanias fue el tetrarca de Abilene, un pequeño territorio al noroeste de Damasco, mencionado en la cuidadosa datación que hace Lucas del inicio del ministerio de Juan el Bautista. Lucas 3:1 sitúa la aparición profética de Juan en el año decimoquinto de Tiberio César, cuando Lisanias gobernaba Abilene. La evidencia histórica confirma la existencia de un Lisanias que gobernó esta región en el período que Lucas describe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3079', 'spa', 'Lisias; el tribuno romano (Claudio Lisias) que rescató a Pablo y comandaba la guarnición de Jerusalén', 'Claudio Lisias fue el tribuno romano (comandante militar) a cargo de la guarnición en la Fortaleza Antonia de Jerusalén durante la última visita de Pablo a la ciudad. Cuando una turba atacó a Pablo en los atrios del templo, Lisias lo rescató con soldados, confundiéndolo inicialmente con un revolucionario egipcio (Hechos 21:31-38). Al descubrir una conspiración para asesinar a Pablo, lo trasladó bajo fuerte custodia a Cesarea ante el gobernador Félix (Hechos 23:26ss). Su carta oficial a Félix lo identifica como «Claudio Lisias»: Claudio era su nombre romano de familia y Lisias su nombre personal griego. Sus acciones, aunque interesadas, providencialmente protegieron a Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3080', 'spa', 'liberación, disolución, desatadura (especialmente del vínculo matrimonial)', 'Este sustantivo designa la acción de soltar o liberar de ataduras, ya sean cadenas literales, obligaciones morales o relaciones legales. En 1 Corintios 7:27, Pablo lo emplea en el contexto del matrimonio, preguntando si alguien ha sido liberado de su esposa. El significado raíz del término implica desatar o dejar libre de un compromiso vinculante. En el uso paulino, la palabra aborda la cuestión pastoral de si buscar o no la disolución de un vínculo conyugal en tiempos de dificultad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3081', 'spa', 'conviene, es provechoso, es mejor, resulta ventajoso', 'Este verbo impersonal expresa que algo es ventajoso, provechoso o preferible; que conviene o beneficia. En el uso clásico aparecía frecuentemente en contextos comerciales o en deliberaciones éticas sobre qué curso de acción produce mayor beneficio. Jesús lo emplea en Lucas 17:2 como una advertencia severa: más le valdría a alguien que le colgaran una piedra de molino al cuello antes que hacer tropezar a uno de estos pequeños. La gravedad del lenguaje subraya las consecuencias eternas de desviar a otros de la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3082', 'spa', 'Listra, ciudad de la provincia romana de Licaonia en Asia Menor, vinculada a los viajes misioneros de Pablo.', 'Listra era una pequeña colonia romana en la región de Licaonia, destacada en el libro de Hechos como parada recurrente en los viajes misioneros de Pablo. Allí Pablo sanó a un hombre lisiado de nacimiento y fue erróneamente adorado como Hermes (Acts 14:8-18), y más tarde fue apedreado casi hasta la muerte. Timoteo, fiel colaborador de Pablo, era oriundo de Listra (Acts 16:1-2), lo que convierte a esta ciudad en un hito personal del ministerio apostólico. Pablo recuerda sus sufrimientos allí en 2 Timothy 3:11 como testimonio de la liberación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3084', 'spa', 'Redimir, rescatar; liberar mediante el pago de un precio, librar de la esclavitud por medio de una compra', 'Esta palabra expresa el concepto de poner en libertad a alguien mediante el pago de un precio de rescate. En el mundo antiguo se refería comúnmente a pagar para liberar a un prisionero de guerra, recuperar una prenda o manumitir a un esclavo. El Nuevo Testamento la emplea teológicamente para la redención espiritual. Lucas 24:21 expresa la esperanza frustrada de los discípulos de que Jesús fuera «el que había de redimir a Israel». Tito 2:14 declara que Jesús «se dio a sí mismo por nosotros para redimirnos de toda iniquidad». Y 1 Pedro 1:18 recuerda a los creyentes que fueron «rescatados, no con cosas corruptibles como oro o plata, sino con la sangre preciosa de Cristo». La imagen enfatiza una liberación costosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3085', 'spa', 'Redención; el acto de rescatar o liberar mediante el pago de un precio', 'Este sustantivo describe el acto o proceso de la redención: poner en libertad a los cautivos mediante el pago de un rescate. Mientras el verbo enfatiza la acción de redimir, el sustantivo se centra en la redención como hecho consumado o evento esperado. Lucas 1:68 bendice a Dios porque «ha visitado y redimido a su pueblo», celebrando la redención realizada por medio del Mesías venidero. Asimismo, Ana habló del niño Jesús «a todos los que esperaban la redención en Jerusalén» (Lucas 2:38). Hebreos 9:12 declara que Cristo «obtuvo eterna redención» por medio de su propia sangre, no de sacrificios animales. El término capta tanto el costo como la plenitud de la obra redentora de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3086', 'spa', 'redentor, libertador, rescatador', 'Este sustantivo designa a quien libera cautivos pagando un rescate o efectuando una liberación. Conlleva tanto connotaciones comerciales (comprar la libertad) como significado teológico profundo (rescate divino). En Hechos 7:35, Esteban lo aplica a Moisés, a quien Dios envió como gobernante y libertador de Israel, prefigurando la obra redentora mayor de Cristo. El término vincula la liberación histórica del Éxodo con la redención espiritual del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3087', 'spa', 'Candelero — soporte para sostener lámparas, incluyendo la menorá del templo y los candeleros simbólicos de las iglesias. λυχνία es el soporte sobre el', 'Candelero — soporte para sostener lámparas, incluyendo la menorá del templo y los candeleros simbólicos de las iglesias. λυχνία es el soporte sobre el cual se coloca una lámpara (λύχνος) para que su luz ilumine toda la estancia. En los Evangelios Sinópticos, Jesús emplea la imagen proverbialmente: nadie enciende una lámpara y la pone debajo de un almud en vez de sobre el candelero (Mt 5:15; Mc 4:21; Lc 8:16; 11:33). Hebreos 9:2 hace referencia al candelabro de oro del tabernáculo — la menorá de siete brazos. En Apocalipsis, el término adquiere un simbolismo poderoso: siete candeleros de oro representan siete iglesias (Ap 1:12-13, 20; 2:1, 5), y los dos testigos son llamados dos candeleros que están delante del Señor (Ap 11:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3088', 'spa', 'Lámpara — lámpara portátil de aceite usada para iluminación doméstica, frecuentemente metáfora de iluminación espiritual o testimonio. λύχνος es la lá', 'Lámpara — lámpara portátil de aceite usada para iluminación doméstica, frecuentemente metáfora de iluminación espiritual o testimonio. λύχνος es la lámpara común de aceite y arcilla del hogar mediterráneo antiguo — pequeña, portátil y colocada sobre un candelero para alumbrar la habitación. Jesús recurre a este objeto cotidiano para formular algunos de sus puntos más memorables: nadie enciende una lámpara y la esconde debajo de un almud (Mt 5:15; Mc 4:21; Lc 8:16; 11:33). La lámpara del cuerpo es el ojo (Mt 6:22; Lc 11:34). Juan el Bautista era un λύχνος que ardía y alumbraba (Jn 5:35). En Apocalipsis, la lámpara desaparece de Babilonia como señal de desolación total (Ap 18:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3089', 'spa', 'Desatar, soltar, liberar, disolver, quebrantar o destruir; desde el desate fisico hasta la anulacion legal y la disolucion cosmica.', 'Desatar, soltar, liberar, disolver, quebrantar o destruir; desde el desate fisico hasta la anulacion legal y la disolucion cosmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3090', 'spa', 'Loida, abuela de Timoteo', 'Loida fue la abuela materna de Timoteo, el joven colaborador de Pablo. En 2 Timoteo 1:5, Pablo elogia su fe sincera, que ella transmitió a su hija Eunice y a su nieto Timoteo. Su fe judía y su instrucción en las Escrituras sentaron las bases para el posterior ministerio cristiano de Timoteo. Su ejemplo ilustra la transmisión multigeneracional de una herencia piadosa y el papel fundamental de las abuelas en la formación espiritual de la familia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3091', 'spa', 'Lot; sobrino de Abraham que se estableció en Sodoma y fue rescatado antes de su destrucción.', 'Lot (en hebreo לוֹט, «cubierta» o «velo») es el sobrino de Abraham cuya historia en Génesis sirve como arquetipo de advertencia en el NT. Jesús cita los días de Lot como paralelo a los días del Hijo del Hombre: la gente comía, bebía, compraba y vendía hasta que cayó fuego del cielo (Lc 17:28-29). La advertencia «Acordaos de la mujer de Lot» (Lc 17:32) se volvió proverbial como ejemplo del peligro de mirar atrás. Pedro llama a Lot «justo» y presenta su rescate de Sodoma como prueba de que Dios sabe librar de la prueba a los piadosos (2 Pe 2:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3092', 'spa', 'Maát, antepasado de Jesús en la genealogía de Lucas', 'Maát aparece únicamente en la genealogía de Jesús según Lucas, situado entre Matatías y Nagay en el linaje postexílico. Como muchos nombres en esta sección genealógica, no se conserva información histórica adicional más allá del registro genealógico mismo. El nombre puede derivar de raíces hebreas, aunque su etimología e identificación histórica permanecen inciertas. Su inclusión en la genealogía lucana subraya la continuidad del linaje davídico hasta Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3093', 'spa', 'Magadán, localidad cercana al mar de Galilea mencionada en Mateo 15:39', 'Magadán era una localidad situada en las riberas del mar de Galilea o en sus cercanías, mencionada únicamente en Mateo 15:39 después de que Jesús alimentara a los cuatro mil. Su ubicación exacta permanece sin identificar, aunque posiblemente guarde relación con Magdala. El pasaje paralelo en Marcos 8:10 emplea el nombre «Dalmanutá», lo cual sugiere que ambos podrían ser nombres variantes de la misma región o de localidades muy próximas entre sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3094', 'spa', 'Magdalena — epíteto de María procedente de la ciudad de Magdala, en la orilla occidental del mar de Galilea. Magdalena no es un nombre personal sino u', 'Magdalena — epíteto de María procedente de la ciudad de Magdala, en la orilla occidental del mar de Galilea. Magdalena no es un nombre personal sino un epíteto geográfico — «la de Magdala» — adjunto exclusivamente a María de Magdala para distinguirla de las demás Marías en los relatos evangélicos. La ciudad de Magdala (actual Migdal) se hallaba en la ribera occidental del mar de Galilea, y su nombre deriva del hebreo migdal («torre»). Las 12 apariciones en el NT identifican a la misma mujer: aquella de quien fueron expulsados siete demonios (Mc 16:9; Lc 8:2), que presenció la crucifixión (Mt 27:56; Mc 15:40; Jn 19:25), que visitó el sepulcro vacío (Mt 28:1; Mc 16:1; Lc 24:10; Jn 20:1) y que fue la primera testigo del Señor resucitado (Jn 20:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3095', 'spa', 'magia, hechicería, artes ocultas', 'Este sustantivo designa la práctica de la magia o la hechicería. Originalmente se refería a las enseñanzas religiosas de los magos persas, pero su significado se extendió a las artes ocultas en general. En Hechos 8:11, Simón el Mago había asombrado a los samaritanos con sus artes mágicas durante largo tiempo, captando su atención. El término refleja la difundida práctica de la magia en el mundo grecorromano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3096', 'spa', 'practicando magia, ejerciendo hechicería', 'Este participio describe a alguien activamente dedicado a la práctica de la magia o la hechicería. Denota la actividad continua de un mago o hechicero que emplea técnicas sobrenaturales u ocultas. Hechos 8:9 presenta a Simón con este participio, identificándolo como alguien que venía practicando la magia en la ciudad y asombrando al pueblo samaritano. Esta caracterización prepara el contraste dramático cuando Simón se encuentra con el genuino poder apostólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3097', 'spa', 'Mago; sabio o sacerdote persa, o (peyorativamente) hechicero, mago charlatán que practica artes ocultas.', 'Del antiguo persa ''maguš'', este término entró al griego con el prestigio de la casta sacerdotal meda: hombres versados en astronomía, interpretación de sueños y ritos sagrados. En Matthew 2, los Magos que visitan al niño Jesús encarnan el sentido honorable: sabios extranjeros guiados por una estrella que ofrecen regalos regios. Pero para el siglo I el término había adquirido también una connotación oscura: un practicante de artes mágicas, un charlatán que comercia con poder oculto. En Acts 13:6-8, Bar-Jesús (Elimas) es llamado mago en este sentido peyorativo: falso profeta y hechicero que se opone al evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3098', 'spa', 'Magog, nación aliada con Gog en la batalla escatológica', 'Magog aparece en Génesis 10:2 como descendiente de Jafet y en Ezequiel 38-39 como un pueblo aliado con Gog en una invasión de Israel en los últimos tiempos. Apocalipsis 20:8 emplea estos nombres de manera simbólica para designar a las naciones engañadas por Satanás después del milenio, congregadas para la batalla final contra el pueblo de Dios. Su identificación sigue siendo debatida, con propuestas que van desde los escitas hasta una representación simbólica de naciones hostiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3099', 'spa', 'Madián (Μαδιάμ), transliteración griega del hebreo Midián, región desértica al este del golfo de Aqaba', 'Este nombre propio aparece en Hechos 7:29 durante el recuento que Esteban hace del exilio de Moisés. Cuando Moisés huyó de Egipto tras matar al egipcio, se estableció en la tierra de Madián, una región seminómada asociada con los descendientes de Abraham a través de Cetura. La forma griega conserva el nombre hebreo tanto del patriarca Madián como del territorio geográfico que habitaron sus descendientes: el desierto donde Moisés se encontró con Dios en la zarza ardiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3100', 'spa', 'Hacer discípulo, formar como seguidor; ser discipulado o instruido en los caminos del reino.', 'Μαθητεύω significa hacer de alguien un discípulo — incorporarlo a una relación de aprendizaje y seguimiento. Derivado de μαθητής (discípulo/aprendiz), este verbo porta todo el peso de la Gran Comisión: «Id y haced discípulos a todas las naciones» (Mt 28:19). Aparece tanto en sentido activo como pasivo: José de Arimatea «había sido hecho discípulo» de Jesús (Mt 27:57), un escriba instruido para el reino saca de su tesoro lo nuevo y lo viejo (Mt 13:52), y Pablo y Bernabé «hicieron muchos discípulos» en Derbe (Hch 14:21). El verbo implica no solo la conversión inicial sino una formación continua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3101', 'spa', 'Discípulo, aprendiz; seguidor comprometido de un maestro, especialmente de Jesús', 'Con 263 apariciones en el Nuevo Testamento, μαθητής es el término emblemático para quienes siguen a Jesús. En el griego clásico designaba al estudiante de un filósofo o retórico, pero los Evangelios y Hechos lo concentran casi exclusivamente en los seguidores de Jesús, tanto los Doce como el círculo más amplio de adherentes. Implica no solo aprendizaje intelectual, sino adhesión personal, obediencia y misión compartida (Mt 5:1; 10:1). También aparece para los discípulos de Juan el Bautista y los alumnos de los fariseos, conservando su sentido pedagógico original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3102', 'spa', 'μαθήτρια — discípula, aprendiz femenina; forma femenina de μαθητής que designa a una seguidora de Jesús', 'Esta rara forma femenina aparece únicamente en Hechos 9:36 para describir a Tabita (Dorcas), identificada explícitamente como una mujer que era discípula. El término porta el mismo significado que su equivalente masculino: alguien que aprende de un maestro y lo sigue. En el contexto neotestamentario, designa a una seguidora de Jesús. El uso deliberado de la forma femenina por parte de Lucas resalta la condición de Tabita como discípula comprometida, reconocida por sus buenas obras y su caridad hacia los necesitados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3103', 'spa', 'Μαθουσάλα — transliteración griega de Matusalén, patriarca antediluviano célebre por su extraordinaria longevidad', 'Este nombre aparece en la genealogía de Jesús según Lucas (3:37), que traza el linaje hasta los patriarcas primigenios anteriores a Noé. Matusalén, hijo de Enoc y abuelo de Noé, es famoso en Génesis 5:27 por haber vivido 969 años, la vida más larga registrada en las Escrituras. La forma griega sigue la transliteración de la Septuaginta del nombre hebreo, que posiblemente significa ''hombre del dardo'' o ''cuando él muera, vendrá'', vinculado tradicionalmente con el momento del Diluvio. Su inclusión conecta a Jesús con la historia más antigua de la humanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3104', 'spa', 'Μεννά — nombre propio en la genealogía de Jesús, personaje sin otros registros bíblicos o históricos conocidos', 'Este nombre aparece únicamente en Lucas 3:31, dentro de la sección genealógica entre David y el exilio. A diferencia de la genealogía de Mateo, que sigue la línea real a través de Salomón, Lucas traza el linaje por medio de Natán, hijo de David. Menná es una de varias figuras desconocidas en esta porción de la ascendencia de Jesús. Las variantes en los manuscritos (Μεννᾶς, Μαϊνάν) sugieren cierta incertidumbre en la transmisión textual, pero su inclusión subraya el interés de Lucas por establecer el linaje davídico auténtico de Jesús a través de una rama diferente del árbol genealógico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3105', 'spa', 'Estar loco, desvariar; estar fuera de sí, ya sea por frenesí divino, influencia demoníaca o aparente demencia.', 'Enraizado en la idea de frenesí o furor, μαίνομαι en el NT describe sistemáticamente a alguien percibido como loco o fuera de sí. Cuando Jesús habla de manera provocadora, sus adversarios lo desestiman como endemoniado y «loco» (Juan 10:20). A la criada Rode le dicen «¡Estás loca!» cuando anuncia la milagrosa liberación de Pedro (Hechos 12:15). Festo acusa a Pablo de que las muchas letras lo han vuelto loco (Hechos 26:24), cosa que Pablo niega rotundamente (26:25). Pablo también advierte que los incrédulos que entren a un culto carismático podrían concluir que los que hablan «están locos» (1 Cor 14:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3107', 'spa', 'Bienaventurado, dichoso, feliz -- declarado favorecido por Dios; fórmula de congratulación divina, no mera emoción.', 'Μακάριος abre el sermón más célebre de Jesús: «Bienaventurados los pobres en espíritu» (Mt 5:3). A lo largo de sus 50 apariciones, no funciona como expresión de felicidad emocional, sino como declaración divina de un estatus privilegiado: un macarismo que proclama a alguien inscrito en el favor de Dios. Las Bienaventuranzas (Mt 5:3-11; Lc 6:20-22) constituyen su epicentro teológico, complementadas por Stg 1:12, las siete bienaventuranzas del Apocalipsis y la cita paulina del Salmo 32 (Ro 4:7-8). El griego clásico reservaba μακάριος para los dioses y los muertos dichosos; el Nuevo Testamento lo redirige hacia quienes el mundo menos llamaría afortunados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3108', 'spa', 'Bienaventuranza, dicha; el estado de ser bendecido o de experimentar el favor divino', 'Esta palabra describe el estado de ser bienaventurado o la dicha que procede del favor divino. Aparece en la enseñanza de Pablo sobre la justificación por la fe. Romanos 4:6 habla de «la bienaventuranza del hombre a quien Dios atribuye justicia sin obras», citando el salmo de David sobre los pecados perdonados. Romanos 4:9 pregunta si «esta bienaventuranza» es solo para los circuncidados o también para los incircuncisos, respondiendo que Abraham fue justificado por la fe antes de ser circuncidado. Gálatas 4:15 evoca la bienaventuranza inicial de los gálatas al recibir el evangelio de Pablo. El término enfatiza no una mera felicidad, sino el estado privilegiado de aquellos a quienes Dios ha favorecido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3109', 'spa', 'Macedonia — la provincia romana en el norte de Grecia, una region clave en los viajes misioneros y la fundacion de iglesias de Pablo.', 'Macedonia — la provincia romana en el norte de Grecia, una region clave en los viajes misioneros y la fundacion de iglesias de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3110', 'spa', 'Macedonio; habitante de Macedonia, la región del norte de Grecia, patria de Alejandro Magno y luego provincia romana.', 'Este sustantivo identifica a una persona originaria de Macedonia, el reino del norte de Grecia que produjo a Alejandro Magno y posteriormente se convirtió en provincia romana. En la célebre visión macedónica de Pablo (Hechos 16:9), un hombre suplica «Pasa a Macedonia y ayúdanos», redirigiendo la misión apostólica hacia Europa. Aristarco y Gayo son identificados como macedonios que viajaban con Pablo (Hechos 19:29; 27:2). En 2 Corintios 9:2, 4, Pablo usa la generosa ofrenda de los macedonios para estimular a los corintios a una liberalidad semejante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3111', 'spa', 'μάκελλον — mercado de carne o de alimentos, préstamo del latín macellum', 'Este préstamo del latín aparece en 1 Corintios 10:25, donde Pablo aborda la cuestión de comer carne que pudiera haber sido sacrificada a los ídolos. Un macellum era un mercado cubierto al estilo romano donde se vendían diversos alimentos, especialmente carne. La instrucción de Pablo es práctica: los creyentes debían comprar y comer lo que se vendiera en el mercado público sin plantear cuestiones de conciencia sobre sus asociaciones paganas. El origen latino del término refleja las realidades comerciales de la vida urbana grecorromana, donde estos mercados eran elementos habituales de la infraestructura de las ciudades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3112', 'spa', 'Lejos, a lo lejos; adverbio de distancia espacial que indica alejamiento respecto de un punto de referencia.', 'Derivado del acusativo femenino de μακρός y con función adverbial, este vocablo expresa distancia espacial o lejanía. En Marcos 12:34, Jesús le dice al escriba «no estás lejos del reino de Dios», empleando la distancia como metáfora de cercanía espiritual. El hijo pródigo parte «a una provincia lejana» (Lc 15:13), y estando «aún lejos» su padre lo ve (Lc 15:20), transmitiendo ese conmovedor sentido de vasta separación seguida de reencuentro. En Mateo 8:30 un hato de cerdos pacía «lejos de ellos», y en Juan 21:8 los discípulos estaban «no lejos de tierra». El español «lejos» y el francés «loin» captan fielmente esta noción de distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3113', 'spa', 'De lejos, a distancia — adverbio que indica lejanía espacial de un observador o viajero. μακρόθεν es un adverbio espacial que significa «desde lejos» ', 'De lejos, a distancia — adverbio que indica lejanía espacial de un observador o viajero. μακρόθεν es un adverbio espacial que significa «desde lejos» o «a distancia», y aparece en algunos de los momentos más cargados emocionalmente de los Evangelios. Pedro sigue a Jesús μακρόθεν tras el arresto (Mt 26:58; Mc 14:54; Lc 22:54). Las mujeres que habían seguido desde Galilea contemplan la crucifixión μακρόθεν (Mt 27:55; Mc 15:40; Lc 23:49). El publicano ora de pie μακρόθεν, sin atreverse a acercarse (Lc 18:13). En cada caso, la distancia es tanto física como psicológica, expresando cautela, duelo o indignidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3114', 'spa', 'El verbo μακροθυμέω (makrothymeo), literalmente ''de temperamento largo'' (μακρός + θυμός), significa ejercer paciencia o longanimidad: soportar la demo', 'El verbo μακροθυμέω (makrothymeo), literalmente ''de temperamento largo'' (μακρός + θυμός), significa ejercer paciencia o longanimidad: soportar la demora, la provocación o la adversidad sin ceder a la ira ni a la desesperación. En la parábola del siervo que no perdona, ambos deudores suplican ''ten paciencia conmigo'' (Mt 18:26, 29). Pablo declara que el amor ''es paciente'' (1 Co 13:4), y Santiago exhorta a los creyentes a ''tener paciencia hasta la venida del Señor'', como el labrador que espera la lluvia (Stg 5:7-8). Dios mismo es paciente, no queriendo que ninguno perezca (2 P 3:9), y la paciencia de Abraham aseguró la promesa (He 6:15). El árabe صَبَرَ, el hebreo הֶאֱרִיךְ אַפַּיִם, el coreano 오래 참다 y el español ''tener paciencia'' expresan la misma constancia perseverante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3115', 'spa', 'Paciencia, longanimidad, tolerancia — la constancia firme que refrena la ira y persevera en la adversidad. μακροθυμία combina μακρός («largo») y θυμός', 'Paciencia, longanimidad, tolerancia — la constancia firme que refrena la ira y persevera en la adversidad. μακροθυμία combina μακρός («largo») y θυμός («pasión, ira»), produciendo un término que literalmente significa «de ánimo largo», lo opuesto a ser impulsivo. Aparece catorce veces en el Nuevo Testamento, destacadamente como fruto del Espíritu (Gá 5:22), sello distintivo del amor (1 Co 13:4) y atributo del propio Dios que demora el juicio para dar lugar al arrepentimiento (Ro 2:4; 9:22; 1 Ti 1:16; 2 P 3:15). Pablo la enumera entre las virtudes que caracterizan un ministerio apostólico genuino (2 Co 6:6) y los rasgos de carácter que los creyentes deben cultivar (Ef 4:2; Col 1:11; 3:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3116', 'spa', 'μακροθύμως — pacientemente, con longanimidad y perseverancia; forma adverbial de μακρόθυμος', 'Este adverbio aparece en Hechos 26:3, donde Pablo pide al rey Agripa que lo escuche con paciencia. El término combina ''largo'' (μακρός) y ''pasión/ira'' (θυμός), significando literalmente ''largo de temperamento'', lo opuesto a impulsivo o iracundo. Describe la disposición de soportar a otros o las circunstancias sin perder la compostura ni ceder a la ira. La petición de Pablo reconoce que su defensa requiere atención cuidadosa a las costumbres y controversias judías, solicitando el tipo de escucha paciente que no se precipita a emitir juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3117', 'spa', 'Largo o lejano; extendido en longitud espacial, duración temporal o distancia geográfica.', 'Adjetivo que abarca tanto el espacio como el tiempo. En los Evangelios Sinópticos, Jesús condena a quienes ''por pretexto hacen largas oraciones'' (Matt 23:14; Mark 12:40; Luke 20:47); aquí μακρός describe extensión temporal, algo prolongado y dilatado. Pero la misma palabra también alcanza el espacio geográfico: el hijo pródigo viaja a un ''país lejano'' (Luke 15:13), y el noble parte a una ''tierra distante'' (Luke 19:12). La declaración de Pedro en Pentecostés de que la promesa se extiende a ''todos los que están lejos'' (Acts 2:39) usa el sentido espacial con resonancias teológicas de inclusión gentil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3118', 'spa', 'μακροχρόνιος — longevo, que disfruta de una vida prolongada', 'Este adjetivo aparece en Efesios 6:3, dentro de la cita que hace Pablo del quinto mandamiento sobre honrar a los padres. El término significa literalmente ''largo en tiempo'', combinando μακρός (largo) y χρόνος (tiempo). En la Septuaginta y el NT, se refiere específicamente a la longevidad como una bendición divina. La promesa ''para que seas de larga vida sobre la tierra'' adapta la promesa mosaica original de larga vida en la tierra de Canaán a una aplicación cristiana más amplia, donde honrar a los padres sigue vinculado a la bendición de días prolongados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3119', 'spa', 'enfermedad, dolencia; padecimiento o debilidad corporal que aflige al ser humano', 'Este vocablo designa enfermedad, dolencia o debilidad del cuerpo: males físicos que aquejan a las personas. El Evangelio de Mateo lo emplea tres veces en resúmenes del ministerio sanador de Jesús. Mateo 4:23 describe a Jesús «sanando toda enfermedad y toda dolencia en el pueblo». Mateo 9:35 repite un lenguaje casi idéntico, y 10:1 otorga a los doce discípulos autoridad para «sanar toda enfermedad y toda dolencia». La repetición subraya el alcance total del poder sanador de Jesús: ninguna dolencia escapaba a su autoridad. Sus curaciones manifestaban la irrupción del reino de Dios, revirtiendo los efectos de la caída.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3120', 'spa', 'Suave, fino, delicado; referido a ropa: lujoso; referido a personas: afeminado o moralmente indulgente.', 'μαλακός significa fundamentalmente «suave» — suave al tacto, fino en textura, delicado en calidad. En los Evangelios, Jesús contrasta a su rudo profeta Juan el Bautista con quienes visten «ropas suaves» (μαλακά), las que se usan en los palacios reales (Mateo 11:8; Lucas 7:25). La palabra también puede describir blandura moral o autoindulgencia; en 1 Corintios 6:9 Pablo la emplea en una lista de vicios donde probablemente denota a quienes son moralmente débiles o ceden al exceso sensual. El rango semántico va desde la textura física hasta el lujo y la caracterización moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3121', 'spa', 'Maleleēl (Μαλελεήλ) — transliteración griega de Mahalalel, patriarca antediluviano en la genealogía de Jesús', 'Este nombre aparece en Lucas 3:37 entre los ancestros antediluvianos que trazan el linaje de Jesús hasta Adán. Mahalalel, mencionado en Génesis 5:12-17, fue hijo de Cainán y padre de Jared, y vivió 895 años según el texto masorético. El nombre hebreo posiblemente significa ''alabanza de Dios'' o ''Dios es esplendor''. La inclusión de estos patriarcas primigenios por parte de Lucas subraya la conexión de Jesús no solo con la historia de Israel sino con los orígenes universales de la humanidad, estableciéndolo como el segundo Adán cuyo linaje se remonta al primer hombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3122', 'spa', 'Especialmente, sobre todo, ante todo — adverbio superlativo que marca el grado más alto o la prioridad. μάλιστα es la forma superlativa de μάλα («muy»', 'Especialmente, sobre todo, ante todo — adverbio superlativo que marca el grado más alto o la prioridad. μάλιστα es la forma superlativa de μάλα («muy»), que funciona como adverbio con el significado de «especialmente», «sobre todo» o «ante todo». Sus 12 apariciones en el NT suelen destacar un elemento de un grupo para darle énfasis particular. Pablo lo utiliza con especial frecuencia: los creyentes deben hacer el bien a todos, «especialmente» a los de la familia de la fe (Gá 6:10); saludos de todos los santos, «especialmente» los de la casa de César (Fil 4:22); trae los libros, «sobre todo» los pergaminos (2 Ti 4:13). En Hechos, introduce a Agripa como «especialmente» versado en las costumbres judías (Hch 26:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3123', 'spa', 'Más, más bien -- adverbio comparativo que intensifica el grado o expresa preferencia.', 'El griego μᾶλλον (comparativo de μάλα, ''muy'') funciona como adverbio comparativo con el significado de ''más'' o ''más bien'', ya sea intensificando una cualidad por encima de un punto de referencia explícito o implícito, ya sea expresando preferencia entre alternativas. Jesús lo emplea memorablemente en argumentos de menor a mayor: «¿cuánto más vuestro Padre dará cosas buenas?» (Mt 7:11), «¿no valéis vosotros mucho más que ellas?» (Mt 6:26). Pablo lo usa para la preferencia enfática --πολλῷ μᾶλλον, ''mucho más'' (Fil 2:12)-- y para el correctivo ''más bien'' (Ef 4:28; 5:11). Sus 81 apariciones abarcan todos los corpus principales del NT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3124', 'spa', 'Malchos (Μάλχος) — nombre del siervo del sumo sacerdote cuya oreja Pedro cortó en Getsemaní', 'Este nombre aparece solo en Juan 18:10, identificando al siervo del sumo sacerdote a quien Pedro hirió con una espada durante el arresto de Jesús. Juan es el único evangelista que nombra a esta persona, quizás porque escribió más tarde, cuando los involucrados ya no corrían riesgo de represalias. El nombre es una forma helenizada de la palabra hebrea y aramea para ''rey'' (מֶלֶךְ), posiblemente indicando servicio real o simplemente un nombre común entre siervos. Lucas añade que Jesús sanó la oreja cortada, mostrando su compasión incluso hacia quienes venían a arrestarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3125', 'spa', 'μάμμη — abuela, término familiar para la madre del padre o de la madre', 'Esta palabra aparece en 2 Timoteo 1:5, donde Pablo menciona a Loida, la abuela de Timoteo, junto con su madre Eunice. Originalmente una palabra infantil para ''madre'' (similar a ''mamá''), μάμμη llegó a significar específicamente ''abuela'' en el griego posterior. La mención de ambas mujeres por parte de Pablo resalta la transmisión multigeneracional de una fe genuina dentro de la familia de Timoteo. Esta referencia es significativa porque muestra que la formación cristiana de Timoteo comenzó antes del ministerio de Pablo, arraigada en la fe sincera de sus ancestras maternas, probablemente creyentes judías que reconocieron a Jesús como el Mesías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3126', 'spa', 'Mamón; riqueza o bienes materiales personificados, vistos como un señor rival de Dios.', 'μαμωνᾶς es un préstamo arameo (mamona, «riqueza» o «posesiones») que Jesús utiliza para personificar las riquezas como un señor en competencia que exige lealtad. El dicho «No podéis servir a Dios y a Mamón» (Mateo 6:24; Lucas 16:13) plantea la elección como absoluta — dos amos, dos lealtades. En Lucas 16:9 Jesús paradójicamente insta a usar «las riquezas injustas» para hacer amigos para la eternidad, y en Lucas 16:11 la fidelidad con el mamón se convierte en prueba de aptitud para las verdaderas riquezas. El origen arameo del término le confiere una resonancia casi demoníaca en oídos griegos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3127', 'spa', 'Manaen (Μαναήν) — compañero de crianza de Herodes el tetrarca, profeta y maestro cristiano en Antioquía', 'Este nombre aparece en Hechos 13:1 entre los profetas y maestros de la iglesia en Antioquía. Lucas destaca específicamente que Manaén fue ''criado junto con'' (σύντροφος) Herodes el tetrarca, indicando que fue compañero de infancia o hermano de crianza de Herodes Antipas, el gobernante que decapitó a Juan el Bautista y se burló de Jesús antes de la crucifixión. El nombre hebreo (Menahem) significa ''consolador''. La presencia de Manaén en el liderazgo eclesial demuestra cómo el evangelio penetró incluso las cortes de los gobernantes, produciendo discípulos de los estratos sociales más elevados que abandonaron sus privilegios para servir a Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3128', 'spa', 'Manasés; nombre del hijo primogénito de José y de un rey de Judá', 'Este nombre hebreo (que significa «el que hace olvidar») identifica a dos figuras bíblicas relevantes. Manasés fue el primogénito de José, nacido en Egipto, cuyos descendientes formaron una de las tribus de Israel. Aunque el menor Efraín recibió la bendición mayor de Jacob, la tribu de Manasés obtuvo un territorio considerable a ambos lados del Jordán. Apocalipsis 7:6 incluye a la tribu de Manasés entre los 144.000 siervos sellados de Dios. Mateo 1:10 (dos veces) menciona a otro Manasés: el impío rey de Judá cuyo reinado de 55 años incluyó idolatría y derramamiento de sangre inocente, aunque luego se arrepintió en el cautiverio babilónico. Su presencia en la genealogía de Jesús demuestra la gracia de Dios obrando a través de linajes imperfectos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3129', 'spa', 'Aprender mediante el estudio, la instruccion o la experiencia; averiguar o llegar a conocer un hecho.', 'Aprender mediante el estudio, la instruccion o la experiencia; averiguar o llegar a conocer un hecho.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3130', 'spa', 'μανία — locura, demencia, perturbación mental extrema o frenesí', 'Este sustantivo aparece en Hechos 26:24, cuando Festo interrumpe la defensa de Pablo ante Agripa, exclamando que su mucho estudio lo ha vuelto loco. La palabra puede denotar insania literal o, como en este caso, describir a alguien cuyas ideas parecen tan radicales que parece desquiciado. En el griego clásico, el término se usaba tanto para la locura clínica como para el frenesí divino o el entusiasmo. Festo no puede procesar el relato de Pablo sobre la resurrección y el llamado divino dentro de su marco racionalista romano, así que lo atribuye a la demencia. Pablo responde con calma que sus palabras son de verdad y cordura, no de locura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3131', 'spa', 'Maná; el alimento milagroso semejante al pan que Dios proveyó a Israel en el desierto, luego tipo del sustento celestial.', 'Maná — del hebreo מָן הוּא («¿Qué es esto?») — es el alimento misterioso que Dios hizo llover diariamente durante los cuarenta años de Israel en el desierto. En el NT funciona tipológicamente: Jesús contrasta el maná que comieron los padres y aun así murieron con el verdadero pan del cielo que da vida eterna (Juan 6:31, 49). Hebreos 9:4 recuerda la urna de oro con maná guardada en el arca del pacto como memorial de la provisión divina. En Apocalipsis 2:17 el Cristo resucitado promete «maná escondido» al vencedor fiel — símbolo de sustento íntimo y escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3132', 'spa', 'μαντεύομαι — practicar la adivinación, profetizar por medios sobrenaturales, decir la buenaventura', 'Este verbo aparece en Hechos 16:16, donde describe a una joven esclava que tenía un espíritu de adivinación y producía grandes ganancias a sus amos mediante la lectura de la fortuna. La palabra deriva de μάντις (profeta/vidente) y en el griego clásico se refería a la búsqueda de conocimiento sobrenatural a través de diversas artes mánticas. La joven seguía al grupo de Pablo proclamándolos siervos del Dios Altísimo, palabras técnicamente ciertas pero de origen demoníaco. Finalmente, Pablo ordenó al espíritu que saliera de ella, demostrando que incluso las proclamaciones espirituales precisas de fuentes ocultistas deben rechazarse, ya que su origen deslegitima el mensaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3133', 'spa', 'μαραίνω — marchitar, desvanecer o extinguir; consumirse', 'Este verbo aparece en Santiago 1:11, ilustrando cómo el rico se marchitará en sus empresas, igual que la hierba se seca bajo el sol abrasador. La palabra significa literalmente apagar o extinguir (originalmente se usaba para el fuego) y luego se extendió para describir plantas que se marchitan o personas que se consumen. Santiago emplea la imagen de Isaías 40:6-8, contrastando la gloria transitoria de la riqueza con la Palabra permanente de Dios. Las actividades y logros del rico, como la belleza de la flor silvestre, resultan efímeros: el calor se intensifica, la flor cae y su hermosura perece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3135', 'spa', 'Perla; gema preciosa formada en un molusco, usada literal y figuradamente para expresar valor espiritual supremo.', 'Una perla, la gema lustrosa atesorada en todo el Mediterráneo antiguo y el Cercano Oriente. Jesús recurre al extraordinario valor de la perla en dos enseñanzas memorables: echar perlas a los cerdos (Mt 7:6), donde la sabiduría se malgasta ante quienes no pueden apreciarla, y el mercader que lo vende todo por una perla de gran precio (Mt 13:45-46), imagen del valor incomparable del reino. En el Apocalipsis, Babilonia se engalana con perlas como símbolo de riqueza extravagante (Ap 17:4; 18:12, 16), y las puertas de la Nueva Jerusalén son cada una una sola perla (Ap 21:21). Primera de Timoteo 2:9 advierte contra el adorno ostentoso con perlas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3136', 'spa', 'Marta; nombre propio derivado del arameo que significa ''señora'' o ''ama,'' llevado por la hermana de María y Lázaro de Betania. Marta (del arameo marta,', 'Marta; nombre propio derivado del arameo que significa ''señora'' o ''ama,'' llevado por la hermana de María y Lázaro de Betania. Marta (del arameo marta, ''señora'' o ''ama'') es la hermana de María y Lázaro, residente en Betania cerca de Jerusalén. Lucas 10:38-42 la presenta como aquella ''afanada con mucho servicio'' mientras su hermana se sentaba a los pies de Jesús, una escena que se ha vuelto emblemática de la tensión entre el servicio activo y la devoción contemplativa. En Juan 11, Marta emerge como mujer de fe profunda: sale al encuentro de Jesús tras la muerte de Lázaro y confiesa: ''Yo creo que tú eres el Cristo, el Hijo de Dios'' (Juan 11:27), una de las declaraciones cristológicas más significativas del Cuarto Evangelio. Todas las traducciones simplemente transliteran el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3137', 'spa', 'María / Mariam -- nombre propio de varias mujeres del NT, entre ellas la madre de Jesús y María Magdalena.', 'Μαρία (forma helenizada) y Μαριάμ (forma semítica indeclinable) transliteran el nombre hebreo-arameo Miryam, llevado por al menos seis mujeres en el Nuevo Testamento. La más prominente es María la madre de Jesús, figura central de los relatos de la infancia y presente al pie de la cruz (Jn 19:25) y en el aposento alto (Hch 1:14). María Magdalena, primer testigo de la resurrección (Jn 20:1-18), es la segunda portadora más frecuente. Otras incluyen a María de Betania (Lc 10:39), María mujer de Cleofas (Jn 19:25) y María de Roma (Ro 16:6). Las dos formas griegas reflejan variación estilística, no semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3138', 'spa', 'Marcos (Márkos); nombre propio de origen latino que designa a Juan Marcos, compañero de Pablo, Bernabé y Pedro.', 'Μάρκος es la forma griega del nombre latino Marcus, llevado por Juan Marcos, una figura significativa en la iglesia primitiva. Era primo de Bernabé (Col 4:10), acompañó a Pablo y Bernabé en su primer viaje misionero antes de separarse en Panfilia (Hch 13:13; 15:37-39), y más tarde se reconcilió con Pablo, quien lo llamó «útil para el ministerio» (2 Ti 4:11). Pedro lo llama afectuosamente «mi hijo» (1 P 5:13), y la tradición lo identifica como autor del Evangelio de Marcos. Todas las traducciones vierten el nombre fonéticamente: francés «Marc», alemán «Markus», español «Marcos».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3139', 'spa', 'μάρμαρος — mármol, piedra caliza cristalina apreciada para construcción y escultura', 'Esta palabra aparece en Apocalipsis 18:12, dentro de la lista de artículos de lujo que ya nadie compra tras la caída de Babilonia. Originalmente designaba cualquier piedra cristalina que brillase (de μαρμαίρω, ''brillar''), y posteriormente pasó a significar específicamente mármol, la piedra caliza blanca ampliamente utilizada en la arquitectura y el arte grecorromano. La inclusión del mármol en el cargamento de Babilonia por parte de Juan subraya la opulencia y grandeza arquitectónica de la ciudad. El colapso de este comercio simboliza la caída de sistemas económicos edificados sobre la explotación y el lujo en lugar de la justicia, haciéndose eco de las denuncias proféticas contra la riqueza desmedida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3140', 'spa', 'Testificar, dar testimonio; en voz pasiva: ser atestiguado o gozar de buen testimonio.', 'Μαρτυρέω se encuentra en el corazón del vocabulario neotestamentario del testimonio. Juan el Bautista «vino para dar testimonio (μαρτυρήσῃ) de la luz» (Jn 1:7), y el verbo recorre como hilo de oro el Evangelio de Juan, donde testificar de la verdad es un tema central. En voz pasiva, el significado se desplaza de dar testimonio a recibirlo: ser acreditado o gozar de buena reputación, como cuando los siete diáconos son descritos como «varones de buen testimonio» (Hch 6:3). El verbo conjuga así la dimensión forense del testimonio con la personal de la proclamación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3141', 'spa', 'Testimonio, atestiguacion; el acto o contenido de dar testimonio, especialmente acerca de Cristo y el evangelio.', 'Testimonio, atestiguacion; el acto o contenido de dar testimonio, especialmente acerca de Cristo y el evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3142', 'spa', 'Testimonio, testificación, prueba; evidencia presentada o declaración que atestigua la verdad, incluyendo el tabernáculo del testimonio. Este sustanti', 'Testimonio, testificación, prueba; evidencia presentada o declaración que atestigua la verdad, incluyendo el tabernáculo del testimonio. Este sustantivo lleva la doble fuerza de «prueba» y «declaración pública». En los Evangelios aparece frecuentemente en la frase «para testimonio a ellos» (Mt 8:4; Mr 1:44), donde un acto de obediencia se convierte en evidencia viva. Jesús advierte que sus seguidores serán llevados ante gobernadores y reyes «como testimonio» (Mt 10:18; Mr 6:11). Pablo habla del evangelio del reino proclamado «como testimonio a todas las naciones» (Mt 24:14). El término también evoca el «tabernáculo del testimonio» del Antiguo Testamento (Hch 7:44), vinculándolo a las tablas del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3143', 'spa', 'Testificar solemnemente, dar testimonio firme o afirmar con gravedad; poner a otros por testigos de la verdad declarada.', 'Verbo de testimonio solemne y público, empleado cuando el hablante compromete su credibilidad personal con la verdad de lo que declara. Pablo lo utiliza en momentos decisivos: al defender su ministerio ante los ancianos de Éfeso (Hch 20:26), al afirmar su evangelio ante Agripa (Hch 26:22) y al exhortar a los gálatas y efesios a captar el peso de sus palabras. Más que habla casual, es una declaración de verdad en la que uno pone su reputación en juego, con la gravedad propia de un tribunal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3144', 'spa', 'Testigo; quien atestigua lo que ha visto o conocido, desarrollando luego el sentido de ''martir''.', 'Testigo; quien atestigua lo que ha visto o conocido, desarrollando luego el sentido de ''martir''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3145', 'spa', 'μασάομαι — masticar, morder o roer, especialmente con los dientes', 'Este verbo aparece en Apocalipsis 16:10, describiendo a personas que se mordían la lengua de dolor durante el juicio de la quinta copa. La forma en voz media enfatiza la acción reflexiva: se mordían sus propias lenguas. Este detalle gráfico retrata un dolor extremo que provoca una respuesta física involuntaria; sin embargo, Juan señala que aun así rehusaron arrepentirse. La imagen evoca tanto una reacción fisiológica literal al tormento como un sufrimiento metafóricamente autoinfligido. A pesar de un juicio tan intenso destinado a provocar el arrepentimiento, los corazones endurecidos persisten en la blasfemia en lugar de volverse a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3146', 'spa', 'Azotar, flagelar; castigo judicial o punitivo con látigo, aplicado a Jesús en su pasión y a discípulos perseguidos.', 'μαστιγόω se refiere específicamente a la flagelación con un látigo o azote, un castigo formal que podía ser judicial (administrado por soldados romanos) o disciplina sinagogal. Jesús lo predice tres veces en sus anuncios de la pasión (Mt 20:19; Mc 10:34; Lc 18:33), y enmarca el costo del discipulado cuando advierte que sus seguidores serán azotados en las sinagogas (Mt 10:17; Mt 23:34). El autor de Hebreos lo extiende metafóricamente a la disciplina divina (He 12:6). El español ''azotar'' denota golpear con un instrumento dedicado, coincidiendo con la precisión del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3147', 'spa', 'μαστίζω — azotar, flagelar o golpear como castigo o medio de interrogación', 'Este verbo aparece en Hechos 22:25, cuando Pablo pregunta al centurión si es lícito azotar a un ciudadano romano sin haber sido condenado. La palabra deriva de μάστιξ (látigo/azote) y describe la práctica brutal de golpear con varas o látigos, frecuente en los interrogatorios romanos. La pregunta de Pablo invoca su protección legal como ciudadano romano, quien no podía ser azotado sin juicio previo. Este momento revela el uso estratégico que Pablo hacía de su ciudadanía para protegerse y abrir camino legal al avance del evangelio, mostrando que los cristianos, aunque se someten a la autoridad, también ejercen sabiamente sus derechos legales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3148', 'spa', 'Azote o flagelo; literalmente instrumento de castigo, figuradamente enfermedad o aflicción concebida como latigazo divino.', 'La imagen griega clásica es vívida: un látigo chasqueando sobre caballos o el azote impulsando soldados. En el NT, μάστιξ se desdobla en dos registros. En sentido figurado, describe enfermedades y aflicciones como ''azotes'' divinos que marcan y atormentan el cuerpo. La mujer con flujo de sangre es sanada ''de su azote'' (Mark 5:29, 34), y las multitudes se agolpan hacia Jesús para que todos los que tenían ''azotes'' pudieran tocarlo (Mark 3:10; Luke 7:21). En sentido literal, la palabra designa el instrumento físico del castigo romano: Pablo está a punto de ser ''examinado con azotes'' (Acts 22:24), y los héroes del AT ''experimentaron escarnios y azotes'' (Heb 11:36).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3149', 'spa', 'pecho, seno; la parte frontal del torso superior, a veces referido específicamente al seno femenino', 'Esta palabra se refiere al pecho o seno, la parte frontal superior del torso. En contextos bíblicos puede aludir tanto a la anatomía masculina como femenina, aunque a menudo con referencia específica a la lactancia. Lucas 11:27 recoge la exclamación de una mujer que bendice «el vientre que te llevó y los pechos que te amamantaron», celebrando a la madre de Jesús por su papel maternal. Lucas 23:29 cita a Jesús anunciando un tiempo en que dirán «Bienaventurados los pechos que nunca amamantaron», describiendo un juicio tan severo que la infecundidad parecerá preferible a la maternidad. Apocalipsis 1:13 describe al Hijo del Hombre «vestido con una larga túnica y ceñido con un cinturón de oro alrededor del pecho», indicando un atuendo regio y sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3150', 'spa', 'ματαιολογία — palabrería vana, discusión inútil, charla sin sentido', 'Este sustantivo aparece en 1 Timoteo 1:6, donde describe aquello hacia lo cual se han desviado ciertas personas al apartarse de la fe sincera, el corazón puro y la buena conciencia. El compuesto combina μάταιος (vano/vacío) con λογία (habla/discusión), denotando un discurso carente de sustancia y verdad. Pablo lo contrasta con el propósito de su enseñanza: el amor nacido de un corazón limpio. El término sugiere no solo error teológico sino la futilidad de la especulación desligada del núcleo ético y espiritual del evangelio. Tal palabrería genera controversias y disputas en lugar de la obra de Dios que se realiza por fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3151', 'spa', 'ματαιολόγος — hablador vano, persona que dice palabras vacías o sin sentido', 'Este adjetivo aparece en Tito 1:10, donde Pablo advierte sobre personas rebeldes, habladores de vanidades y engañadores, especialmente los del partido de la circuncisión. La palabra combina μάταιος (vano) con λόγος (palabra/discurso), describiendo a quienes enseñan cosas carentes de verdad y sustancia. Estos individuos no están simplemente equivocados sino que son insubordinados, desviando familias enteras por ganancias deshonestas. La descripción de Pablo retrata a personas que usan lenguaje religioso para promover falsas enseñanzas, cuya elocuencia enmascara la vacuidad de su contenido y la corrupción de sus motivos. Deben ser silenciados para proteger a la comunidad de fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3152', 'spa', 'Vano, vacío, inútil; de cosas que carecen de sustancia, valor o efecto; de personas, necio o engañado.', 'En el pensamiento griego, μάταιος describe todo aquello que no logra su propósito o carece de sustancia real. Pablo lo emplea para exponer la vaciedad del razonamiento mundano (1 Cor 3:20) y advertir que sin la resurrección, la fe misma sería inútil (1 Cor 15:17). La evidencia multilingüe es notablemente uniforme: el español ''vana'', el francés ''vain'' y el alemán ''eitel'' convergen en el mismo núcleo semántico de vacuidad e infructuosidad. En Acts 14:15, Pablo y Bernabé exhortan a los de Listra a apartarse de ''cosas vanas'' —ídolos sin vida— hacia el Dios viviente, mostrando que la palabra puede caracterizar sistemas enteros de creencia como huecos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3153', 'spa', 'vanidad, futilidad; cualidad de lo que carece de propósito, valor o sentido', 'Esta palabra expresa la idea de vanidad, futilidad o vacuidad: lo carente de propósito y de resultado significativo. Pablo la emplea teológicamente para describir la condición caída de la humanidad. Romanos 8:20 declara que la creación «fue sometida a vanidad» a causa de la caída: el mundo natural comparte la maldición del hombre, frustrado en alcanzar su propósito original. Efesios 4:17 advierte a los creyentes que ya no caminen «en la vanidad de su mente» como los gentiles, cuyo pensamiento oscurecido por el pecado produce un razonamiento vacío y sin rumbo. 2 Pedro 2:18 describe a falsos maestros pronunciando «palabras infladas y vanas», impresionantes en apariencia pero huecas y engañosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3154', 'spa', 'ματαιόω — hacer vano o fútil; volverse necio o vacío en el pensamiento', 'Este verbo aparece en Romanos 1:21, describiendo cómo la humanidad, conociendo a Dios, se negó a honrarle o darle gracias, volviéndose fútil en sus razonamientos. La forma pasiva indica que «fueron hechos vanos» o «se envanecieron»: sus procesos de pensamiento se tornaron inútiles y sin valor. No se trata de incapacidad intelectual sino de rebelión moral: rechazar la verdad sobre Dios conduce a la corrupción cognitiva. Su supuesta sabiduría se convirtió en necedad. El verbo capta cómo apartarse del Creador no lleva a la iluminación sino a una oscuridad creciente, pues las mentes diseñadas para la verdad se deterioran cuando se desconectan de su objeto propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3156', 'spa', 'Mateo, uno de los doce apóstoles, anteriormente recaudador de impuestos; también llamado Leví.', 'Nombre propio de uno de los doce apóstoles de Jesús, un recaudador de impuestos llamado desde su mesa de cobro a seguir a Cristo (Mt 9:9). La forma semítica detrás del griego sugiere ''don de Dios''. Aparece en todas las listas apostólicas (Mt 10:3, Mr 3:18, Lc 6:15, Hch 1:13) y tradicionalmente se lo identifica con Leví hijo de Alfeo, lo cual vincula los relatos de llamamiento en Mateo y Marcos. En las listas apostólicas se lo empareja constantemente con Tomás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3160', 'spa', 'Ματταθά (Mattathá) — nombre propio en la genealogía de Jesús, presente en el relato de Lucas', 'Este nombre aparece en Lucas 3:31, dentro de la sección genealógica entre David y José. Como muchos nombres en esta parte de la genealogía de Lucas, Mattathá es desconocido fuera de esta referencia. Su origen hebreo (Mattatá) significa «don de Yahvé». La genealogía de Lucas difiere de la de Mateo en esta sección, trazando la línea a través de Natán en vez de Salomón, lo que sugiere ramas distintas de los descendientes de David. Estos nombres menos conocidos establecen la legítima ascendencia davídica de Jesús mediante un registro cuidadoso, incluso cuando los individuos no ocuparon posiciones prominentes en la historia política de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3162', 'spa', 'Espada o cuchillo grande; usado literalmente como arma y figuradamente para el juicio divino, la persecución o el conflicto', 'Espada o cuchillo grande; usado literalmente como arma y figuradamente para el juicio divino, la persecución o el conflicto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3163', 'spa', 'Pelea, contienda o conflicto; discordia que surge de disputas o intereses encontrados.', 'Sustantivo derivado del verbo μάχομαι (pelear), que abarca desde el combate físico hasta las disputas verbales y la discordia interpersonal. En el Nuevo Testamento aparece exclusivamente en sentido figurado de contiendas y querellas, no de batallas militares. Santiago 4:1 pregunta memorablemente de dónde vienen estas ''guerras y peleas'', señalando los deseos internos como raíz. Pablo lo emplea para describir tanto conflictos externos (2 Co 7:5) como las disputas estériles que nacen de controversias necias (2 Ti 2:23, Tit 3:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3164', 'spa', 'Pelear, disputar o reñir; entrar en conflicto verbal o físico con otro.', 'Verbo deponente que abarca desde el combate físico en el griego clásico hasta las riñas y disputas verbales del Nuevo Testamento. En Juan 6:52 los judíos ''disputaban entre sí'' sobre la enseñanza de Jesús acerca de comer su carne, mientras que en Hechos 7:26 Moisés encuentra a dos israelitas peleando e intenta reconciliarlos. Pablo instruye a Timoteo que el siervo del Señor no debe ser contencioso (2 Ti 2:24), y Santiago 4:2 conecta sin rodeos el pelear con los deseos insatisfechos. El énfasis constante recae sobre la disputa y la contienda entre personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3165', 'spa', 'Yo, pronombre de primera persona; casos oblicuos derivados de raíz diferente (genitivo ἐμοῦ, etc.)', 'El pronombre de primera persona «yo» funciona como la autorreferencia básica en griego. La forma nominativa ἐγώ (frecuentemente ἐγών ante vocales) puede reforzarse con la partícula -γε para crear ἔγωγε, con el sentido de «yo al menos» o «por mi parte». Un rasgo interesante: mientras el nominativo proviene de una raíz, los casos oblicuos (genitivo ἐμοῦ, dativo ἐμοί, acusativo ἐμέ) derivan de un tronco completamente distinto, reflejo de patrones indoeuropeos antiguos conservados en la lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3166', 'spa', 'μεγαλαυχέω — jactarse grandemente, alardear o hacer afirmaciones desmesuradas', 'Este verbo aparece en Santiago 3:5, donde Santiago emplea la lengua como ilustración de algo pequeño que se jacta de grandes cosas. El compuesto combina μέγας (grande) con αὐχέω (jactarse), intensificando la idea básica de jactancia hasta convertirla en pretensiones grandiosas y desmesuradas. Santiago compara la lengua con un pequeño fuego que incendia un gran bosque: su capacidad de destrucción excede con creces su tamaño. El contexto advierte sobre el poder del habla para causar un daño desproporcionado. Aunque pequeña, la lengua pretende lograr mucho y con frecuencia produce un daño proporcional a sus alardes y mentiras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3167', 'spa', 'μεγαλεῖος — magnífico, espléndido, poderoso; obras o hechos extraordinarios', 'Este adjetivo aparece en Hechos 2:11 durante Pentecostés, cuando los judíos visitantes oyen a los discípulos proclamar las grandezas de Dios en diversas lenguas. El término denota grandiosidad y magnificencia: cosas dignas de asombro y alabanza. En la Septuaginta traduce frecuentemente palabras hebreas referidas a los hechos poderosos de Dios en la historia, como la creación, el éxodo y la conquista. El asombro de la multitud en Pentecostés no proviene solo del milagro lingüístico, sino de escuchar los grandes actos de Dios proclamados en sus lenguas maternas, cumpliendo la profecía de Joel sobre el derramamiento del Espíritu y revirtiendo la maldición de Babel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3168', 'spa', 'majestad, grandeza; esplendor o magnificencia propia de la realeza o de Dios', 'Esta palabra transmite majestad, magnificencia o grandeza sobrecogedora: el esplendor propio de la realeza y, de modo especial, de Dios. Lucas 9:43 describe la reacción de la multitud cuando Jesús sanó al muchacho endemoniado: estaban «asombrados de la majestad de Dios» manifestada a través de Jesús. Hechos 19:27 recoge la advertencia del platero Demetrio de que la predicación de Pablo amenaza el templo de Artemisa, temiendo que «su majestad» sea destruida y pierda su estatus divino. 2 Pedro 1:16 contrasta el testimonio ocular con los mitos: los apóstoles «fuimos testigos oculares de su majestad» en la Transfiguración, cuando oyeron la voz del Padre declarando a Jesús su Hijo amado. El vocablo enfatiza la gloria divina visible y manifiesta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3169', 'spa', 'μεγαλοπρεπής — magnífico, sublime, majestuoso; que corresponde a la grandeza', 'Este adjetivo aparece en 2 Pedro 1:17, donde describe la gloria majestuosa desde la cual vino la voz durante la transfiguración de Jesús. El compuesto combina μέγας (grande) con πρέπω (ser apropiado), denotando una magnificencia acorde con la grandeza. Pedro apela a esta experiencia como testigo ocular para demostrar que el testimonio apostólico sobre el poder y la venida de Cristo se funda en una revelación divina real, no en mitos ingeniosamente inventados. La gloria majestuosa que presenció en el monte autenticó la identidad de Jesús como Hijo amado de Dios, proporcionando certeza sobre la palabra profética y el regreso del Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3170', 'spa', 'Magnificar, glorificar, alabar; engrandecer o ampliar — declarando grandeza o aumentando extensión', 'El verbo μεγαλύνω, derivado de la raíz μέγας (''grande''), puede tomar dos direcciones: engrandecer a alguien mediante la palabra — alabar, exaltar, magnificar — o hacer algo más grande en tamaño o extensión. El Magnificat de María abre con el ejemplo por excelencia: ''Mi alma engrandece al Señor'' (Lucas 1:46), donde μεγαλύνει significa declarar la grandeza de Dios en alabanza. El sentido físico, menos frecuente, aparece cuando Jesús acusa a los escribas de hacer anchas sus filacterias (Mateo 23:5), y cuando Pablo espera que su ministerio sea ''engrandecido'' (2 Corintios 10:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3171', 'spa', 'μεγάλως — grandemente, en gran manera, sobremanera', 'Este adverbio aparece en Filipenses 4:10, donde Pablo expresa su gran gozo porque los filipenses han reanudado su interés por él. El término modifica verbos para indicar intensidad o grado: no simplemente regocijarse, sino regocijarse grandemente. El afecto de Pablo hacia la iglesia de Filipos impregna toda esta carta; el apoyo económico que le brindaron durante su encarcelamiento le produjo una profunda gratitud. Sin embargo, Pablo aclara de inmediato que su contentamiento no depende de las circunstancias, pues ha aprendido a estar contento en toda situación. Su gran gozo no proviene del regalo en sí, sino del fruto espiritual que este demuestra en quienes lo ofrecen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3172', 'spa', 'majestad; grandeza divina, esplendor y poder soberano propios de Dios', 'Este vocablo, estrechamente relacionado con G3168, subraya la majestad divina: la grandeza, el esplendor y el poder soberano que solo a Dios corresponden. La Carta a los Hebreos lo emplea dos veces para describir la posición exaltada de Cristo. Hebreos 1:3 declara que, tras purificar los pecados, Cristo «se sentó a la diestra de la Majestad en las alturas», un título que resalta la suprema grandeza de Dios. Hebreos 8:1 afirma igualmente que tenemos un sumo sacerdote «sentado a la diestra del trono de la Majestad en los cielos». Judas 25 atribuye «gloria, majestad, dominio y autoridad» al único Dios, nuestro Salvador, por medio de Jesucristo. El término enfatiza la grandeza incomparable de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3173', 'spa', 'Grande; de tamaño físico, rango, intensidad o grado; comparativo ''mayor'' y superlativo ''el más grande''', 'Μέγας es el adjetivo griego estándar para ''grande'' en prácticamente toda dimensión: tamaño, sonido, importancia e intensidad. Una ''gran ciudad'', una ''gran voz'', un ''gran mandamiento'' y un ''gran temor'' emplean la misma palabra. Lo teológicamente interesante de su uso neotestamentario es cómo la magnitud física se funde con la significación espiritual: la ''gran luz'' de Mt 4:16 es luminosa y salvífica a la vez, y el ''gran gozo'' de los magos (Mt 2:10) trasciende lo meramente emocional. Las formas comparativas y superlativas cobran especial peso en la enseñanza de Jesús sobre la grandeza en el reino, invirtiendo deliberadamente las jerarquías mundanas de rango y poder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3174', 'spa', 'μέγεθος — grandeza, magnitud, tamaño o grandiosidad', 'Este sustantivo aparece en Efesios 1:19, donde Pablo ora para que los creyentes conozcan la supereminente grandeza de su poder para con nosotros los que creemos. La palabra denota magnitud o tamaño, ya sea dimensión física o grandeza metafórica. Aquí describe la magnitud incomprensible del poder de Dios, el mismo poder que resucitó a Cristo de entre los muertos y lo sentó a la diestra de Dios. Pablo desea que los creyentes comprendan no solo que Dios tiene poder, sino la extraordinaria grandeza de ese poder que obra activamente a favor de quienes confían en él, un poder que transforma, sostiene y garantiza la glorificación final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3175', 'spa', 'magnates, grandes; personas poderosas, adineradas o de alto rango social', 'Este vocablo designa a los grandes de la tierra: quienes detentan poder, riqueza y elevada posición social. Se refiere a la élite, los magnates, las figuras influyentes que moldean la sociedad. Marcos 6:21 lo emplea en la corte de Herodes, quien ofreció un banquete «a sus nobles, a los comandantes militares y a los principales de Galilea», es decir, al círculo íntimo del poder. Apocalipsis 6:15 enumera a quienes se esconden de la ira divina: «los reyes de la tierra, los grandes, los generales, los ricos y los poderosos», abarcando todo estrato de autoridad humana. Apocalipsis 18:23 lamenta la caída de Babilonia porque «tus mercaderes eran los magnates de la tierra», destacando el poder económico corrompido por el lujo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3176', 'spa', 'Ser o llegar a ser muy grande', 'Este verbo describe la acción de volverse muy grande o alcanzar grandeza. La evidencia léxica muestra su uso con ciudades como sujeto, como en el ejemplo «la ciudad llegará a ser muy grande». Pertenece a una familia de palabras centrada en el concepto de magnitud e importancia, y transmite la idea de un crecimiento notable en tamaño, poder o relevancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3177', 'spa', 'Traducir, interpretar; trasladar una palabra o frase de un idioma a otro', 'Μεθερμηνεύω significa traducir o interpretar, específicamente trasladar un término de un idioma a otro. En el Nuevo Testamento aparece casi exclusivamente en voz pasiva (''siendo traducido'' o ''que traducido es''), usado cuando los evangelistas explican nombres y frases semíticos para audiencias de habla griega — como ''Emmanuel'' (Mateo 1:23), ''Talita cum'' (Marcos 5:41), ''Gólgota'' (Marcos 15:22) y ''Rabí'' (Juan 1:38). Estas glosas de traducción constituyen una de las evidencias más tempranas de práctica bíblica multilingüe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3178', 'spa', 'embriaguez; estado de intoxicación o hábito de beber en exceso', 'Este vocablo describe la embriaguez, tanto el estado de intoxicación como el patrón habitual de beber en exceso. Pablo lo incluye sistemáticamente entre las conductas incompatibles con la vida del reino. Lucas 21:34 advierte a los discípulos que guarden sus corazones para que no se carguen «de glotonería, embriaguez y afanes de esta vida», evitando que el día del juicio los sorprenda desprevenidos. Romanos 13:13 contrasta el caminar decorosamente, «como de día», con entregarse a «orgías y borracheras». Gálatas 5:21 lo incluye entre las «obras de la carne», advirtiendo que «los que practican tales cosas no heredarán el reino de Dios». El término subraya la pérdida de dominio propio y de vigilancia espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3179', 'spa', 'Remover, trasladar o desplazar de una posición o estado a otro; causar un cambio de lealtad o ubicación.', 'Conlleva la fuerza de una reubicación decisiva, ya sea política, espiritual o física. Dios removió a Saúl y levantó a David (Hch 13:22); el Padre trasladó a los creyentes del dominio de las tinieblas al reino de su Hijo (Col 1:13). Pablo afirma que la fe podría ''remover'' montañas (1 Co 13:2). No implica un mero movimiento, sino un cambio de régimen o condición. En Lucas 16:4, el mayordomo teme ser ''removido'' de su puesto, lo cual subraya el carácter autoritativo del desplazamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3181', 'spa', 'Situado entre dos regiones como frontera; territorio limítrofe, confines (neutro pl. τὰ μεθόρια)', 'Este adjetivo describe un territorio que se encuentra entre dos regiones como zona fronteriza. Aparece en expresiones como «el territorio limítrofe entre Argos y Laconia» o «los confines de Ática y Beocia». El neutro plural τὰ μεθόρια funciona como sustantivo con el significado de «fronteras» o «regiones limítrofes». En la tradición variante del Nuevo Testamento, se refiere a los confines de Tiro y Sidón. La palabra capta el espacio intermedio entre territorios, ya sea geográfico o metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3182', 'spa', 'Embriagar o embriagarse; intoxicarse con vino o, en sentido figurado, con influencia seductora.', 'Forma causativa de μεθύω (estar ebrio), este verbo significa embriagar a alguien o, en voz pasiva, embriagarse uno mismo. Sus usos neotestamentarios abarcan desde lo literal --siervos que comen, beben y se embriagan (Lucas 12:45), o quienes se embriagan de noche (1 Tesalonicenses 5:7)-- hasta lo poderosamente figurado. En Efesios 5:18 Pablo contrasta la embriaguez con vino frente a la plenitud del Espíritu. De manera aún más impactante, Apocalipsis 17:2 presenta a las naciones ''embriagadas'' con el vino de la inmoralidad de Babilonia, una metáfora que el español ''embriagarse'' conserva fielmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3184', 'spa', 'Estar ebrio o embriagado con vino; usado literalmente de la borrachera y figuradamente del estupor espiritual o el exceso.', 'Μεθύω describe el estado de estar ebrio por causa del vino, una condición que el Nuevo Testamento presenta con peso tanto literal como moral. En las bodas de Caná, el milagro de Jesús ocurre después de que los invitados han ''bebido bien'' (Juan 2:10), un uso inusualmente neutro. En otros pasajes la palabra conlleva censura moral aguda: el siervo malvado bebe con los borrachos (Mateo 24:49), los que se embriagan lo hacen de noche (1 Tesalonicenses 5:7), y algunos corintios llegaban a la Cena del Señor embriagados (1 Corintios 11:21). La acusación en Pentecostés de que los apóstoles estaban ebrios (Hechos 2:15) sirve como contraste irónico con el hablar lleno del Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3185', 'spa', 'grande (en tamaño, estatura, edad o importancia); μέγας con declinación completa desde la raíz μεγάλο-', 'El adjetivo «grande» abarca un notable abanico de significados: tamaño físico («un hombre grande a la vista»), estatura plena que indica madurez, y grandeza metafórica de importancia u honor. Su declinación es peculiar: la raíz μεγάλο- aparece en la mayoría de las formas, pero el nominativo y acusativo masculino y neutro emplean las formas más breves μέγας y μέγα. Esta palabra puede describir tanto lo físicamente imponente como lo socialmente relevante, lo que la hace versátil en contextos literales y figurados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3186', 'spa', 'mayor, más grande (formas comparativas o superlativas de μέγας)', 'Esta entrada representa las formas comparativas o superlativas de μέγας: «mayor» o «el más grande». Al igual que el grado positivo, estas formas pueden referirse a magnitud física, madurez indicada por la estatura, o grandeza abstracta en honor e importancia. La flexibilidad de la raíz permite expresar gradaciones de grandeza en todos estos campos semánticos, desde lo concreto y mensurable hasta lo figurado y honorífico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3187', 'spa', 'grande (formas adicionales o variantes de μέγας)', 'Otra forma dentro del paradigma de μέγας, que mantiene el mismo espectro semántico de tamaño físico, estatura madura y grandeza figurada. Las múltiples entradas de Strong para esta raíz reflejan su compleja morfología: distintas raíces para diferentes casos y números, todas expresando variaciones de «grande» tanto en sentido concreto como abstracto. Esta variedad formal no altera el significado fundamental, sino que responde a la riqueza flexiva del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3188', 'spa', 'tinta; líquido oscuro usado como medio para escribir o dibujar', 'La tinta era el medio de escritura cotidiano en el mundo antiguo, elaborada con hollín, goma y agua. Pablo contrasta los corazones escritos por el Espíritu con la mera tinta sobre piedra (2 Co 3:3). El anciano Juan cierra dos de sus cartas expresando que prefiere hablar cara a cara antes que escribir «con tinta» (2 Jn 12; 3 Jn 13). Las tres apariciones neotestamentarias contraponen lo escrito con tinta a la relación viva y personal, subrayando que la tinta es un medio material limitado frente a la acción directa del Espíritu o la presencia humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3189', 'spa', 'negro; de color oscuro', 'El color negro se asocia en la imaginería bíblica con el duelo, el hambre y el juicio. Jesús afirma que nadie puede hacer un solo cabello blanco o negro (Mt 5:36), señalando los límites del control humano. En Apocalipsis, el tercer jinete cabalga un caballo negro que simboliza la hambruna (Ap 6:5), y el sol se vuelve negro durante la convulsión cósmica (Ap 6:12). El griego μέλας abarca desde la oscuridad literal hasta la penumbra metafórica, empleándose tanto en contextos cotidianos como en visiones apocalípticas de devastación y juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3190', 'spa', 'Melea (Μελεά) — nombre propio que aparece en la genealogía de Jesús en el Evangelio de Lucas', 'Este nombre aparece en Lucas 3:31, dentro de la sección genealógica entre David y el exilio. Como muchos individuos en esta porción del linaje lucano, Melea es desconocido fuera de esta referencia. El nombre podría derivarse de raíces hebreas relacionadas con ''plenitud'' o posiblemente ser una forma abreviada de un nombre teofórico más largo. La cuidadosa preservación de estos nombres por parte de Lucas, aun cuando los individuos no dejaron otra huella histórica, demuestra su compromiso con establecer la auténtica descendencia davídica de Jesús a través de registros ancestrales verificables, incluso por líneas familiares menos prominentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3192', 'spa', 'Miel; sustancia dulce natural producida por las abejas, incluyendo la miel silvestre.', 'Término directo para designar la miel, que aparece en el Nuevo Testamento exclusivamente en contextos vívidos y concretos. En Mateo 3:4 y Marcos 1:6, la miel silvestre (μέλι ἄγριον) forma parte de la austera dieta de Juan el Bautista en el desierto --langostas y miel--, evocando una imagen de sencillez profética. En Apocalipsis 10:9-10, el librito que sabe dulce como miel en la boca pero se vuelve amargo en el estómago se convierte en una poderosa imagen del llamado profético. La uniformidad perfecta entre idiomas --''miel'' en español y francés, ''Honig'' en alemán-- refleja su significado estable e inequívoco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3193', 'spa', 'relativo a las abejas, de miel; panal de abejas (κηρίον μελίσσειον); colmena (τὸ μελίσσειον)', 'Este adjetivo se relaciona con las abejas y sus productos. La expresión «panal de abejas» (κηρίον μελίσσειον) aparece en la tradición neotestamentaria. El sustantivo neutro τὸ μελίσσειον puede significar tanto «panal» como «colmena» según el contexto. Los léxicos antiguos también registran μελίσσιον con el sentido de «enjambre». La palabra evoca el mundo productivo de las abejas, desde sus moradas hasta la dulce sustancia que elaboran.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3194', 'spa', 'Melitē (Μελίτη) — la isla de Malta, donde Pablo naufragó', 'Este nombre aparece en Hechos 28:1, identificando la isla donde Pablo y los demás sobrevivientes del naufragio llegaron tras una tempestad angustiosa. La isla, situada al sur de Sicilia en el Mediterráneo central, era conocida entonces como Melita. Los habitantes mostraron una bondad extraordinaria hacia los náufragos, y el ministerio de Pablo allí incluyó la sanidad del padre de Publio, el principal de la isla, y de muchos otros. La precisión geográfica de Lucas continúa su patrón de anclar la historia cristiana en lugares reales y verificables, convirtiendo el viaje de Pablo a Roma en un asunto de registro público.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3195', 'spa', 'Estar a punto de, ir a; como participio, venidero o futuro; también estar dispuesto o demorar', 'Un verbo auxiliar versátil que sustenta el lenguaje neotestamentario de la inminencia futura y el destino divino. En su núcleo señala que algo está a punto de ocurrir — Herodes va a buscar al niño (Mt 2:13), el Hijo del Hombre va a ser entregado (Mt 17:22). Cuando se usa como participio modificando sustantivos, adquiere fuerza adjetival con el sentido de ''venidero'' o ''futuro'', como en el siglo venidero (Mt 12:32) o la ira venidera (Mt 3:7). Dos usos aislados amplían el campo semántico: disposición o prontitud en 2 Pe 1:12 y vacilación o demora en Hch 22:16.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3196', 'spa', 'Miembro, parte del cuerpo; extremidad u organo del cuerpo humano, usado literal y metaforicamente para la iglesia.', 'Miembro, parte del cuerpo; extremidad u organo del cuerpo humano, usado literal y metaforicamente para la iglesia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3198', 'spa', 'Melquisedec; el antiguo rey-sacerdote de Salem que bendijo a Abraham, tipo del sacerdocio eterno de Cristo', 'Μελχισέδεκ es la transliteración griega del hebreo Malki-Tsedeq (''mi rey es justicia''), el misterioso rey-sacerdote de Salem que bendijo a Abraham y recibió diezmos de él (Génesis 14:18-20). En el Nuevo Testamento, las ocho ocurrencias aparecen en Hebreos, donde el autor desarrolla un argumento sostenido de que el sacerdocio de Cristo es ''según el orden de Melquisedec'' (Hebreos 5:6, 10; 6:20; 7:1-17) — superior al sacerdocio levítico porque es eterno y carece de sucesión genealógica. Las traducciones preservan uniformemente el nombre de forma fonética: en español ''Melquisedec.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3199', 'spa', 'El verbo μέλω (melo), usado casi exclusivamente en construcciones impersonales (μέλει + dativo, ''le importa a''), expresa si algo es motivo de preocupa', 'El verbo μέλω (melo), usado casi exclusivamente en construcciones impersonales (μέλει + dativo, ''le importa a''), expresa si algo es motivo de preocupación o interés para alguien. Los discípulos preguntan a Jesús durante la tempestad: ''¿No te importa que perezcamos?'' (Mr 4:38). Marta protesta: ''Señor, ¿no te importa que mi hermana me haya dejado sirviendo sola?'' (Lc 10:40). El asalariado ''no le importan las ovejas'' (Jn 10:13), mientras que a Galión ''nada de esto le importaba'' (Hch 18:17). En sentido positivo, Pedro exhorta a los creyentes a echar sus ansiedades sobre Dios ''porque él tiene cuidado de vosotros'' (1 P 5:7). El árabe يُهِمُّ, el hebreo אִכְפַּת, el coreano 관심/상관 y el alemán ''kümmern'' expresan igualmente preocupación personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3200', 'spa', 'μεμβράνα — pergamino, piel animal tratada utilizada para escribir', 'Este préstamo del latín (membrāna) aparece en 2 Timoteo 4:13, donde Pablo pide a Timoteo que traiga el capote que dejó en Troas y ''especialmente los pergaminos''. Se trataba probablemente de documentos importantes escritos sobre pieles animales tratadas, más duraderas que el papiro. La mención específica sugiere que tenían un valor particular: posiblemente porciones de las Escrituras, documentos legales relativos a su ciudadanía romana, o apuntes para la enseñanza. La petición de Pablo desde la prisión revela su compromiso continuo con la palabra escrita aun cuando la muerte se acercaba. A pesar de enfrentar la ejecución, deseaba acceso a estos documentos, mostrando que el ministerio y el aprendizaje continúan hasta el final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3202', 'spa', 'μεμψίμοιρος — quejumbroso, descontento con su suerte, que halla falta en todo', 'Este adjetivo aparece en Judas 16, describiendo a falsos maestros que son ''murmuradores quejumbrosos'' insatisfechos con su suerte en la vida. El compuesto significa literalmente ''el que culpa a su destino'' (μέμφομαι + μοῖρα), denotando una insatisfacción crónica y la tendencia a hallar defectos en las circunstancias. Judas vincula esta actitud con la impiedad y el seguimiento de deseos impíos. Estos individuos rechazan la autoridad divina mientras se quejan constantemente de las consecuencias, ejemplificando la actitud pretenciosa de quienes exigen autonomía de Dios pero se resienten por no recibir sus bendiciones. Su descontento revela corazones fundamentalmente opuestos a someterse a la voluntad de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3303', 'spa', 'Ciertamente, por una parte — partícula discursiva de afirmación o que introduce el primer miembro de un par correlativo', 'Μέν es una partícula discursiva sutil que opera en dos niveles. Usada de forma absoluta, afirma con la fuerza de ''ciertamente'' o ''en verdad''. Con mayor frecuencia, establece un contraste correlativo: μέν...δέ (''por una parte...por otra''). El español a menudo la deja sin traducir, mientras que el francés d''une part y el alemán zwar captan el matiz contrastivo de manera más explícita. En Hch 1:5, por ejemplo, μέν marca el bautismo de agua de Juan como la primera cláusula que espera su contraparte con δέ sobre el bautismo del Espíritu — un ritmo estructural que recorre la prosa cuidadosa de Lucas y la argumentación teológica de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3304', 'spa', 'más bien, por el contrario; partícula adversativa enfática que expresa certeza o contraste', 'Esta partícula intensifica un contraste o corrige una suposición con fuerza enfática. Jesús declara que los verdaderamente bienaventurados no son solo los que oyen sino los que obedecen (Lc 11:28). Pablo la emplea para reprender la presunción: «¿Quién eres tú, oh hombre, para replicar a Dios?» (Ro 9:20). También la usa retóricamente: «¿Acaso no han oído?», y responde con μενοῦνγε: «¡Ciertamente que sí!» (Ro 10:18). Funciona como correctivo enfático que va desde ''más bien'' hasta ''ciertamente'', abarcando tanto la oposición como la afirmación rotunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3305', 'spa', 'Conjunción que expresa concesión o afirmación: sin embargo, ciertamente, no obstante — marcando contraste o énfasis', 'Una partícula discursiva versátil que señala que el hablante reconoce una realidad antes de girar hacia otra. En su uso más frecuente significa ''sin embargo'' o ''no obstante,'' introduciendo una cláusula concesiva — como cuando los discípulos querían interrogar a Jesús pero nadie se atrevió (Juan 4:27), o cuando muchos creyeron pero no lo confesaban abiertamente (Juan 12:42). También puede llevar una fuerza puramente enfática, ''ciertamente'' o ''en verdad,'' afirmando con peso lo que sigue. Pablo lo usa como ''no obstante'' en 2 Timoteo 2:19, girando de la falsa enseñanza al firme fundamento de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3306', 'spa', 'Permanecer, morar, quedarse; en un lugar: alojarse; en una relación: persistir, habitar; de cosas: perdurar; también esperar, aguardar', 'Μένω es uno de los verbos con mayor carga teológica del Nuevo Testamento, aunque su significado básico es sencillo: quedarse. En la narrativa ordinaria describe alojarse en casa de alguien (Lc 19:5) o permanecer en una ciudad (Hch 9:43). Pero en el Cuarto Evangelio sufre una profunda transformación espiritual. ''Permaneced en mí, y yo en vosotros'' (Jn 15:4): aquí el verbo carga todo el peso de la unión mística, la fidelidad de pacto y la fe perseverante. Un tercer sentido describe la permanencia temporal: ''la palabra de Dios permanece para siempre'' (1 Pe 1:25). El raro sentido de ''esperar'' en Hch 20:5, 23 devuelve el verbo a su uso clásico griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3307', 'spa', 'Dividir en partes o facciones, o repartir y distribuir porciones; separar ya sea de modo destructivo o generoso. Abarca tanto la división destructiva ', 'Dividir en partes o facciones, o repartir y distribuir porciones; separar ya sea de modo destructivo o generoso. Abarca tanto la división destructiva de comunidades como la distribución constructiva de recursos. Cuando Jesús advierte que un reino dividido contra sí mismo no puede sostenerse (Mt 12:25), el verbo conlleva matices de fractura y ruina. Pero cuando reparte los panes entre la multitud en la alimentación de los cinco mil (Mc 6:41), el mismo verbo describe una distribución generosa. Pablo lo emplea para referirse a Dios repartiendo dones a cada creyente (1 Co 7:17, Ro 12:3). El español refleja este abanico con ''dividido'' para el cisma y ''repartir'' para la distribución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3308', 'spa', 'Ansiedad, preocupación o inquietud absorbente por asuntos terrenales; solicitud ansiosa que distrae de la fe.', 'Μέριμνα es la preocupación corrosiva y absorbente que consume la mente con asuntos terrenales. Jesús advierte repetidamente contra ella en las parábolas sinópticas: los afanes de este mundo ahogan la palabra como espinos (Mateo 13:22; Marcos 4:19; Lucas 8:14), y las ansiedades de la vida cotidiana pueden abrumar el corazón (Lucas 21:34). Sin embargo, Pablo rescata un matiz positivo cuando habla de su diaria ''preocupación por todas las iglesias'' (2 Corintios 11:28), mostrando que no toda inquietud es espiritualmente destructiva. La tensión entre la ansiedad dañina y la solicitud piadosa recorre todo el uso neotestamentario del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3309', 'spa', 'Estar ansioso o preocupado; también mostrar interés genuino o preocupación por alguien o algo. En el Sermón del Monte, Jesús repite este verbo como un', 'Estar ansioso o preocupado; también mostrar interés genuino o preocupación por alguien o algo. En el Sermón del Monte, Jesús repite este verbo como un estribillo — «no os afanéis por vuestra vida» (Mt 6:25, 27, 28, 31, 34) — exponiendo la ansiedad como una falta de confianza. Sin embargo, Pablo redime la misma palabra en 1 Corintios 7:32-34 y 12:25, donde preocuparse por las cosas del Señor o por los demás miembros del cuerpo es algo encomiable. La diferencia depende enteramente del objeto y el motivo: la preocupación ansiosa por las provisiones frente a la devoción atenta a Dios y al prójimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3310', 'spa', 'Parte, porción o lote asignado; también distrito o región; usado de la participación en una herencia o relación.', 'Designa una porción que ha sido repartida o que pertenece a alguien por derecho. María escogió la buena ''parte'' (Lucas 10:42); los creyentes participan de la ''herencia'' de los santos en la luz (Colosenses 1:12). También puede significar un distrito geográfico, como en Hechos 16:12, donde se describe a Filipos como ciudad principal de aquel ''distrito'' de Macedonia. Pablo pregunta qué ''parte'' tiene el creyente con el incrédulo (2 Corintios 6:15), extendiendo el término al ámbito de la comunión relacional. El español emplea tanto ''parte'' como ''porción'', reflejando esta doble acepción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3312', 'spa', 'μεριστής — repartidor, distribuidor, el que divide o reparte porciones', 'Este sustantivo aparece en Lucas 12:14, donde Jesús responde a un hombre que le pide resolver una disputa de herencia con su hermano. Jesús pregunta: ''¿Quién me ha puesto sobre vosotros como juez o repartidor?'' El término describe a alguien que asigna porciones o divide propiedades. Jesús rechaza este papel no porque la justicia carezca de importancia, sino porque vino con un propósito mayor que dirimir reclamaciones terrenales. Su misión consiste en proclamar el reino, no en arbitrar disputas patrimoniales. Este rechazo conduce de inmediato a la parábola del rico insensato, advirtiendo contra la codicia y el acumular tesoros terrenales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3313', 'spa', 'Parte, porcion, participacion; region, distrito; seccion, lado; turno en secuencia; trozo o fragmento de algo.', 'Parte, porcion, participacion; region, distrito; seccion, lado; turno en secuencia; trozo o fragmento de algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3315', 'spa', 'μεσιτεύω — actuar como mediador o garante, intervenir entre las partes para asegurar un acuerdo', 'Este verbo aparece en Hebreos 6:17, donde se describe cómo Dios, queriendo demostrar de manera inequívoca la firmeza de su propósito a los herederos de la promesa, la confirmó con un juramento. El término denota actuar como mediador o garante, interponiéndose entre las partes para asegurar un pacto. Lo extraordinario aquí es que Dios mismo actúa como garante de su propia promesa: él media su propio pacto. Al no poder jurar por nadie mayor, juró por sí mismo, haciendo su promesa doblemente segura mediante palabra y juramento, ofreciendo así un firme consuelo a quienes se acogen a la esperanza puesta delante de ellos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3316', 'spa', 'Mediador; aquel que se interpone entre dos partes para lograr reconciliación, pacto o acuerdo.', 'Μεσίτης designa a la persona que interviene entre dos partes para lograr un acuerdo o reconciliación. En el Nuevo Testamento, este poderoso concepto se aplica primero a Moisés, quien sirvió como mediador cuando la Ley fue dada por medio de ángeles en el Sinaí (Gálatas 3:19-20). De manera mucho más significativa, Cristo es declarado el único mediador entre Dios y la humanidad (1 Timoteo 2:5) y el mediador de un pacto nuevo y superior (Hebreos 8:6; 9:15; 12:24). La etimología del término refleja la idea de estar ''en el medio'', captando el sentido posicional de quien se sitúa entre ambas partes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3317', 'spa', 'Medianoche; el punto medio de la noche, que marca un momento decisivo o dramático.', 'Compuesto de μέσος (medio) y νύξ (noche), este sustantivo designa la hora de la medianoche. En el Nuevo Testamento aparece consistentemente como marcador temporal de eventos significativos. Jesús lo menciona como una de las cuatro vigilias en que el señor podría regresar (Marcos 13:35). Un amigo llega a medianoche pidiendo pan (Lucas 11:5), poniendo a prueba los límites de la generosidad entre vecinos. Pablo y Silas oran y cantan himnos a medianoche en la cárcel de Filipos (Hechos 16:25), y Pablo predica hasta la medianoche en Troas (Hechos 20:7). La estructura compuesta es transparente en múltiples idiomas: ''medianoche'' en español, ''minuit'' en francés, ''Mitternacht'' en alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3319', 'spa', 'Medio, en medio -- el centro o interior de un espacio, grupo o situación; uso espacial, social y temporal.', 'Μέσος es el adjetivo griego que significa ''medio'' o ''en medio'', empleado sustantivadamente con el artículo para indicar el punto central de un lugar, reunión o circunstancia. Jesús envía a sus discípulos «como ovejas en medio de lobos» (Mt 10:16), coloca a un niño «en medio» de los Doce (Mt 18:2) y promete estar presente «donde dos o tres están congregados», literalmente «en medio de ellos» (Mt 18:20). El término marca también puntos medios temporales («a mediados de la fiesta», Jn 7:14) y sirve en momentos narrativos dramáticos como Pablo de pie «en medio del Areópago» (Hch 17:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3320', 'spa', 'μεσότοιχον — pared divisoria, muro de separación, barrera entre espacios', 'Este sustantivo aparece en Efesios 2:14, donde Pablo declara que Cristo ''derribó la pared intermedia de separación'' entre judíos y gentiles. El término significa literalmente ''muro del medio'' (μέσος + τοῖχος), una partición que separa espacios. Algunos ven una alusión a la barrera del templo que prohibía el paso de los gentiles a los atrios interiores bajo pena de muerte. En un sentido más amplio, representa toda la separación basada en la Torá que marcaba la identidad distintiva judía. La muerte de Cristo abolió esta barrera, creando una nueva humanidad de ambos grupos, permitiendo que tanto judíos como gentiles se acerquen juntos a Dios por medio de Cristo en un solo Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3321', 'spa', 'medio del cielo, el cenit o punto más alto de la bóveda celeste', 'Este término designa el cenit, el punto directamente sobre la cabeza donde el cielo alcanza su meridiano. En Apocalipsis, los ángeles vuelan «en medio del cielo» para proclamar mensajes visibles a todos los habitantes de la tierra (Ap 8:13; 14:6; 19:17). Esta posición sugiere máxima visibilidad y proclamación universal. Las tres apariciones se encuentran en las visiones apocalípticas de Apocalipsis, donde la geografía cósmica tiene importancia teológica. El griego μεσουράνημα significa literalmente ''medio del cielo'', un término técnico astronómico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3322', 'spa', 'μεσόω — estar a la mitad, hallarse en el punto medio, especialmente referido al tiempo', 'Este verbo aparece en Juan 7:14, donde se indica que ''cuando la fiesta estaba ya a la mitad'' (literalmente ''estando la fiesta mediada''), Jesús subió al templo y comenzó a enseñar. El término describe estar en el punto medio, particularmente de un período de tiempo. Jesús se había quedado en Galilea mientras sus hermanos iban a Jerusalén para la Fiesta de los Tabernáculos, pero a la mitad de la celebración de una semana, apareció públicamente en el templo. Su momento fue estratégico: no buscó notoriedad al inicio de la fiesta, sino que enseñó cuando las multitudes estaban reunidas y sus mentes ocupadas con los temas del festival sobre agua y luz, que él cumpliría de forma extraordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3324', 'spa', 'Lleno, colmado; que describe algo rebosante de contenido, ya sea literal (un recipiente) o figurado (cualidades morales)', 'Adjetivo que significa lleno o colmado, aplicado tanto a recipientes físicos como al carácter moral. Un vaso lleno de vinagre es ofrecido a Jesús en la cruz (Juan 19:29), y una red arrastrada a tierra está llena de 153 peces grandes (Juan 21:11). Más impactante es el uso figurado: Jesús denuncia a los escribas como ''llenos de hipocresía e iniquidad'' (Mateo 23:28), y Pablo cataloga a la humanidad como ''llenos de envidia, homicidio, contienda'' (Romanos 1:29). El español ''llenos'' preserva este doble alcance físico-moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3325', 'spa', 'μεστόω — llenar por completo, colmar, saturar de algo', 'Este verbo aparece en Hechos 2:13, donde los burladores desestiman a los discípulos de Pentecostés diciendo que ''están llenos de mosto'' (literalmente ''habiendo sido llenados por completo de vino dulce''). El término significa llenar completamente o saturar. La acusación era que los discípulos estaban ebrios, lo cual explicaría su comportamiento extraño y su habla incomprensible. Pedro refuta esto de inmediato, señalando que apenas eran las nueve de la mañana. La ironía es profunda: ciertamente estaban llenos, pero no de vino, sino del Espíritu Santo. Este llenado no produjo embriaguez sino un testimonio poderoso en múltiples lenguas, cumpliendo la profecía de Joel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3326', 'spa', 'Con (genitivo: compañía, asociación); después de (acusativo: secuencia temporal) — preposición griega básica de proximidad', 'Esta versátil preposición rige dos casos en el Nuevo Testamento con significados netamente distintos. Con genitivo expresa compañía y asociación — ''con su madre María'' (Mt 2:11), ''Dios con nosotros'' (Mt 1:23 vía Emmanuel) — y es una de las formas más comunes de decir ''con'' en griego koiné. Con acusativo marca la sucesión temporal, ''después de'', como en ''después de seis días'' (Mt 17:1) y ''después de la tribulación'' (Mt 24:29). La distinción de caso se traslada con nitidez a vocablos separados en las lenguas receptoras: español con frente a después de, francés avec frente a après, alemán mit frente a nach.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3327', 'spa', 'Moverse de un lugar o estado a otro; partir, pasar o trasladarse. Compuesto de μετά (''cambio'') y βαίνω (''ir''), este verbo transmite fundamentalmente e', 'Moverse de un lugar o estado a otro; partir, pasar o trasladarse. Compuesto de μετά (''cambio'') y βαίνω (''ir''), este verbo transmite fundamentalmente el cruce de una posición a otra. En los Evangelios describe con mayor frecuencia los desplazamientos físicos de Jesús: partir de una ciudad a la siguiente (Mt 11:1; 12:9; 15:29). Pero en dos pasajes extraordinarios trasciende lo espacial: ''El que oye mi palabra y cree ha pasado de muerte a vida'' (Jn 5:24), eco repetido en 1 Jn 3:14. El español capta el sentido físico con ''partió'' y emplea el mismo ''ha pasado'' para el cruce espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3328', 'spa', 'μεταβάλλω — cambiar de opinión, alterar el parecer o la actitud, dar un giro', 'Este verbo aparece en Hechos 28:6, donde se describe cómo los nativos de Malta ''cambiaron de opinión'' sobre Pablo al ver que no sufría ningún daño por la mordedura de la víbora. Al principio esperaban que se hinchara y muriera, concluyendo que debía ser un asesino a quien la justicia perseguía incluso después de escapar del mar. Cuando nada malo le sucedió, cambiaron su juicio al extremo opuesto, declarando que debía ser un dios. El término denota revertir una posición u opinión. El incidente muestra cuán rápidamente el juicio humano puede oscilar entre extremos, aunque Pablo aparentemente redirigió ese asombro supersticioso hacia la proclamación del Dios verdadero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3330', 'spa', 'Compartir, dar una parte de lo que se posee o impartir generosamente a otro.', 'Va más allá del simple dar para enfatizar el compartir de lo que uno ya posee. Juan el Bautista instó a quienes tenían dos túnicas a ''compartir'' con quien no tiene ninguna (Lucas 3:11). Pablo anhelaba ''impartir'' un don espiritual a los romanos (Romanos 1:11) y describe cómo compartió no solo el evangelio sino ''nuestras propias vidas'' con los tesalonicenses (1 Tesalonicenses 2:8). El español ''compartir'' captura hermosamente esta generosidad participativa: no se trata de deshacerse de todo, sino de dejar que otros participen de lo que uno tiene.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3331', 'spa', 'cambio, remoción, traslación; transferencia de un estado o posición a otro', 'Este sustantivo denota un cambio fundamental o una transferencia. Hebreos lo emplea dos veces: el cambio del sacerdocio levítico al orden de Melquisedec exige un cambio de ley (He 7:12), y al final, las cosas que pueden ser sacudidas serán removidas para que permanezcan las inconmovibles (He 12:27). La ''traslación'' de Enoc (He 11:5) usa la misma raíz: fue transferido de la tierra sin experimentar la muerte. El término implica no una simple modificación sino un desplazamiento o sustitución completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3333', 'spa', 'Mandar llamar, convocar o hacer venir a alguien desde otro lugar.', 'Compuesto de μετά (que implica cambio de lugar) y καλέω (llamar), este verbo significa mandar llamar a alguien, enviar por una persona para que venga desde donde se encuentra. Las cuatro apariciones neotestamentarias se concentran en Hechos, reflejando un registro administrativo e interpersonal. José manda llamar a su padre Jacob (Hch 7:14), a Cornelio se le indica que haga llamar a Pedro (Hch 10:32), Pablo convoca a los ancianos de Éfeso (Hch 20:17) y Félix manda llamar a Pablo para conversar (Hch 24:25). La expresión española «hizo llamar» capta con precisión el matiz causativo de enviar por alguien a distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3334', 'spa', 'μετακινέω — mover de un lugar a otro, desplazar o remover de una posición', 'Este verbo aparece en Colosenses 1:23, donde Pablo advierte a los creyentes que permanezcan en la fe, sin ser movidos de la esperanza del evangelio. La palabra significa desplazar o cambiar de posición. Pablo la emplea metafóricamente para describir el desplazamiento espiritual: ser removidos del fundamento estable de la esperanza evangélica. Habiendo descrito la posición segura de los creyentes en Cristo, ahora enfatiza la necesidad de perseverar. La fe genuina permanece anclada en lugar de ir a la deriva. El participio presente sugiere una resistencia continua contra las fuerzas que intentan apartarlos de la esperanza proclamada en el evangelio que escucharon.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3335', 'spa', 'Participar de, recibir una porción; tomar alimento, comer.', 'El verbo μεταλαμβάνω, compuesto de μετά (''con, después'') y λαμβάνω (''tomar''), significa obtener una parte de algo, participar en ello. En el Nuevo Testamento se divide en dos sentidos. El abstracto abarca recibir una porción de cualquier cosa, desde la disciplina divina (He 12:10) hasta la cosecha del agricultor (2 Ti 2:6). El concreto se reduce a comer: los primeros creyentes compartían alimentos con corazones alegres (Hch 2:46), y Pablo instó a los marineros a comer para sobrevivir (Hch 27:33-34). Ambos sentidos comparten la idea de recibir la porción que a uno le corresponde, pero el alimentario es suficientemente distintivo para marcarlo aparte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3336', 'spa', 'μετάληψις — recepción, participación, acto de recibir algo compartido', 'Este sustantivo aparece en 1 Timoteo 4:3, donde Pablo describe a falsos maestros que prohíben el matrimonio y exigen abstinencia de alimentos que Dios creó para ser recibidos con acción de gracias. La palabra denota participación o recepción de algo. Pablo argumenta que estas cosas creadas son buenas y fueron diseñadas por Dios para que los creyentes las reciban con gratitud. El falso ascetismo que él combate trata la creación material como intrínsecamente mala, contradiciendo la doctrina de que Dios hizo todas las cosas buenas. La recepción apropiada con acción de gracias santifica lo que Dios ha dado, mientras que rechazar sus dones deshonra al Creador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3338', 'spa', 'Sentir pesar o remordimiento; cambiar de parecer sobre una acción pasada, distinto del arrepentimiento pleno (μετάνοια).', 'Μεταμέλομαι expresa pesar emocional o remordimiento por algo ya hecho, una respuesta centrada en los sentimientos que se distingue del arrepentimiento más profundo y transformador de la voluntad que transmite μετανοέω. En la Parábola de los Dos Hijos, el primero ''se arrepintió'' de su negativa y fue a trabajar (Mateo 21:29), mientras que los principales sacerdotes no sintieron siquiera este pesar básico al ver el ministerio de Juan (Mateo 21:32). De modo más impactante, Judas ''sintió remordimiento'' tras traicionar a Jesús (Mateo 27:3), pero ese pesar no lo condujo a la restauración sino a la desesperación. Pablo usa la palabra para describir sus sentimientos complejos sobre una carta dolorosa (2 Corintios 7:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3339', 'spa', 'Transformar, transfigurar o cambiar de forma; una metamorfosis interior que se hace visible exteriormente.', 'Formado a partir de μετά (cambio) y μορφή (forma), este verbo describe una transformación profunda de forma o naturaleza, no una mera alteración externa sino una metamorfosis genuina. Sus cuatro usos neotestamentarios se dividen en dos pares: la transfiguración visible de Jesús en el monte (Mt 17:2, Mr 9:2), donde su rostro y vestiduras irradiaron gloria divina, y la transformación espiritual continua de los creyentes (Ro 12:2, 2 Co 3:18). El mandato paulino de «ser transformados por la renovación de vuestro entendimiento» emplea la voz pasiva, indicando que este cambio es obra de Dios. El español distingue elegantemente entre «transfigurado» (para Jesús) y «transformados» (para los creyentes).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3340', 'spa', 'Arrepentirse, cambiar de parecer; experimentar una reorientacion fundamental del corazon y la conducta hacia Dios.', 'Arrepentirse, cambiar de parecer; experimentar una reorientacion fundamental del corazon y la conducta hacia Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3341', 'spa', 'Arrepentimiento; un cambio profundo de mente y corazón que implica apartarse del pecado y volverse a Dios', 'Arrepentimiento; un cambio profundo de mente y corazón que implica apartarse del pecado y volverse a Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3342', 'spa', 'Entre (espacial o relacional); siguiente, en el intervalo que sigue; entre tanto, en el tiempo intermedio.', 'Preposicion y adverbio cuyo significado central es ''en el espacio intermedio entre dos puntos''. En la mayoria de los usos neotestamentarios marca una relacion de intermediacion espacial o relacional: entre tu y tu hermano (Mt 18:15), entre Abel y Zacarias (Mt 23:35), o el gran abismo fijado entre el paraiso y el tormento (Lc 16:26). Tambien puede indicar intervalos temporales: en Hch 13:42 senala ''el sabado siguiente'' (el que viene en medio), y en Jn 4:31 funciona como adverbio temporal puro con el sentido de ''entre tanto'' o ''mientras tanto''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3343', 'spa', 'Mandar llamar, hacer venir; enviar un mensajero para solicitar la presencia de alguien.', 'Verbo compuesto (meta + pempo) que significa enviar a buscar a alguien, es decir, hacerlo venir por medio de un intermediario. En el Nuevo Testamento aparece exclusivamente en Hechos, donde describe la practica romana y cristiana primitiva de solicitar formalmente la presencia de una persona. Cornelio manda llamar a Pedro (Hch 10:5, 22) y Pedro luego relata haber sido convocado (Hch 11:13). La palabra refleja la dinamica social de la comunicacion indirecta a traves de mensajeros; el espanol ''hacer venir'' capta bien esta fuerza causativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3344', 'spa', 'convertir, transformar, pervertir; cambiar de dirección o naturaleza', 'Este verbo describe la acción de dar vuelta o transformar algo, a veces con connotaciones negativas de perversión. La profecía de Joel anuncia que el sol será ''convertido'' en tinieblas (Hch 2:20, citando Jl 2:31). Pablo advierte que algunos quieren ''pervertir'' el evangelio (Gá 1:7). Santiago exhorta a que la risa sea ''cambiada'' en llanto (Stg 4:9). El rango semántico abarca la transformación cósmica, la corrupción doctrinal y la inversión emocional. El griego μεταστρέφω significa literalmente ''girar hacia otro lado''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3345', 'spa', 'Cambiar la apariencia externa; transformar, disfrazar o aplicar figuradamente.', 'Se centra en la alteración de la forma exterior más que de la naturaleza interior. Pablo «aplicó» (transfirió como figura) ciertas verdades a sí mismo y a Apolos por causa de los corintios (1 Co 4:6). Satanás «se disfraza» de ángel de luz (2 Co 11:14), y sus servidores igualmente se hacen pasar por ministros de justicia (2 Co 11:13, 15). Sin embargo, la misma palabra describe el poder de Cristo para «transformar» el cuerpo humilde de los creyentes en gloria (Fil 3:21). El español capta ambos polos: «apliqué» para la transferencia figurada y «se disfraza» para la mascarada engañosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3346', 'spa', 'Trasladar, transponer, cambiar; apartarse o desertar; pervertir o distorsionar algo convirtiéndolo en su opuesto.', 'Μετατίθημι conlleva la idea fundamental de colocar algo de manera diferente, moverlo de una posición a otra. En su uso físico, describe la traslación de Enoc (Hebreos 11:5) o el traslado de los restos de los patriarcas a Siquem (Hechos 7:16). Pero la palabra se extiende poderosamente al ámbito moral y teológico: Pablo la emplea para referirse a los gálatas que ''se están apartando'' del evangelio (Gálatas 1:6), y Judas la utiliza para quienes ''pervierten'' la gracia de Dios convirtiéndola en libertinaje (Judas 1:4). La progresión del traslado físico a la distorsión teológica muestra cómo los verbos griegos de movimiento desarrollan regularmente sentidos figurados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3347', 'spa', 'μετέπειτα — después, posteriormente, más adelante en el tiempo', 'Este adverbio aparece en Hebreos 12:17, donde el autor señala que Esaú ''después'' buscó la bendición con lágrimas pero fue rechazado, sin hallar oportunidad de arrepentimiento aunque la buscó con fervor. La palabra indica secuencia temporal: lo que vino después de la acción inicial. La historia de Esaú advierte contra la profanidad y el menosprecio de las cosas sagradas. Despreció su primogenitura por una gratificación momentánea, y luego quiso desesperadamente recuperar la bendición que había perdido. La distancia temporal entre el desprecio casual y el arrepentimiento angustiado ilustra cómo las decisiones presentes generan consecuencias futuras que no siempre pueden revertirse, ni siquiera con lágrimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3348', 'spa', 'Participar de, tener parte en; recibir una porcion de algo que se comparte en comun.', 'Metecho significa participar de algo o tener parte en ello, con enfasis en el lado receptivo de la participacion. Aparece en el Nuevo Testamento principalmente en las cartas de Pablo y en Hebreos, abarcando una gama notable de realidades compartidas: participar del pan (1 Co 10:17), compartir la mesa de los demonios al comer alimentos ofrecidos a idolos (1 Co 10:21), alimentarse de leche en vez de alimento solido en la ensenanza (Heb 5:13), y lo mas profundo: Cristo participando de carne y sangre para destruir el poder de la muerte (Heb 2:14). El espanol ''participar'' capta bien la idea de tomar una porcion real de algo mayor que uno mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3349', 'spa', 'μετεωρίζω — estar ansioso o preocupado, hallarse suspendido en la incertidumbre', 'Este verbo aparece en Lucas 12:29, donde Jesús instruye a sus discípulos a no andar ansiosos por lo que comerán o beberán. La palabra significa literalmente ''levantar en alto'' o ''suspender,'' y se usa metafóricamente para describir el estado inquieto y flotante de la ansiedad. En el griego clásico se empleaba para elevar cosas o estar suspendido en la incertidumbre. Jesús la aplica al estado mental de preocupación que mantiene a las personas suspendidas entre posibilidades, sin poder descansar. Su enseñanza sigue la instrucción sobre la provisión de Dios para las aves y las flores, argumentando de lo menor a lo mayor que el Padre ciertamente cuidará de sus hijos, haciendo la ansiedad innecesaria y contraria a la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3350', 'spa', 'Deportación, exilio o reasentamiento forzoso; específicamente la cautividad babilónica de Judá.', 'Término técnico para la migración forzada o deportación, empleado en el Nuevo Testamento exclusivamente en referencia al exilio babilónico dentro de la genealogía de Mateo. Las cuatro apariciones se encuentran en Mateo 1:11-17, donde la deportación a Babilonia funciona como eje estructural que divide la historia de Israel en tres épocas: de Abraham a David, de David al exilio y del exilio a Cristo. La traducción uniforme en diversas lenguas — español «deportación», francés «déportation», alemán «Wegführung» (conducción forzada) — subraya la naturaleza violenta e involuntaria del acontecimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3352', 'spa', 'μετοχή — asociación, participación compartida o comunión en algo que se tiene en común', 'Este sustantivo denota el acto de compartir juntos o participar conjuntamente en algo. Pablo lo usa en 2 Corintios 6:14 en una pregunta retórica sobre qué asociación puede tener la justicia con la iniquidad. La evidencia multilingue (español ''participación,'' francés ''participation,'' alemán ''Gemeinschaft'') enfatiza tanto el aspecto de compartir como la dimensión comunitaria. La tradición léxica muestra usos clásicos que van desde la copropiedad de bienes hasta la participación conjunta en conceptos abstractos. Pablo argumenta que la verdadera comunión requiere valores y lealtades compartidas, haciendo imposible una asociación genuina entre la luz y las tinieblas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3353', 'spa', 'Partícipe, copartícipe; socio, compañero o asociado; quien tiene parte en algo compartido con otros.', 'Metochos describe fundamentalmente a alguien que comparte algo con otros, ya sea un llamamiento, una realidad espiritual o una empresa comercial. El autor de Hebreos lo emplea extensamente: los creyentes son partícipes de Cristo (Heb 3:14), de un llamamiento celestial (Heb 3:1) y del Espíritu Santo (Heb 6:4). La evidencia multilingüe es reveladora: tanto el español partícipes como el alemán Teilhaber subrayan la dimensión de ''tomar parte'', mientras que compañeros (Heb 1:9) desplaza el énfasis hacia la comunión relacional. En Lucas 5:7, el término describe a Jacobo y Juan como socios de Simón en la pesca, anclando su uso más concreto en la cooperación económica cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3354', 'spa', 'μετρέω (metreō) es el acto de medir, ya sea grano, distancia o, lo más memorable en las Escrituras, juicios morales. El dicho de Jesús ''con la medida ', 'μετρέω (metreō) es el acto de medir, ya sea grano, distancia o, lo más memorable en las Escrituras, juicios morales. El dicho de Jesús ''con la medida con que medís, os será medido'' (Mt 7:2; Mr 4:24) constituye el corazón del uso neotestamentario de esta palabra, jugando con las voces activa y pasiva en un mismo proverbio. El sentido activo abarca todas las instancias de medir y asignar medida, incluyendo al ángel que mide el templo en Ap 11:1-2 y la negativa de Pablo a ''medirse a sí mismos por sí mismos'' en 2 Co 10:12. La voz pasiva aparece en la mitad recíproca del proverbio de Jesús. El español capta bien la distinción de voz: ''medís'' (activo) frente a ''os será medido'' (pasivo).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3355', 'spa', 'unidad de medida de líquidos equivalente a unos 34 litros, usada especialmente para agua o vino', 'Este sustantivo masculino designa una unidad de medida para líquidos del mundo antiguo, aproximadamente equivalente al bat hebreo. En Juan 2:6, describe la capacidad de las tinajas de piedra en las bodas de Caná, cada una con capacidad de dos o tres medidas. La evidencia multilingüe subraya de manera uniforme su carácter de unidad de medición. Las fuentes clásicas indican que equivalía al ánfora romana, lo que significa que cada tinaja podía contener entre 70 y 100 litros del agua que Jesús transformó en vino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3356', 'spa', 'tratar con moderación y paciencia a alguien, sobrellevando con mansedumbre su debilidad o ignorancia', 'Este verbo compuesto combina las ideas de respuesta mesurada y contención emocional. En Hebreos 5:2, describe la cualidad esencial de un sumo sacerdote: la capacidad de tratar con mansedumbre a los ignorantes y extraviados. La evidencia interlingüística enfatiza tanto la moderación como la paciencia. El uso clásico señala un punto medio deliberado entre la simpatía excesiva y el juicio severo: el sacerdote puede compadecerse porque él mismo está rodeado de debilidad, lo que le permite responder con compasión mesurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3357', 'spa', 'moderadamente, en grado moderado; no en gran manera', 'Este adverbio expresa un grado o alcance mesurado, indicando algo realizado dentro de límites razonables. En Hechos 20:12, describe el grado de consuelo que experimentaron los creyentes de Éfeso cuando el joven Eutico fue restituido con vida tras su caída mortal. La evidencia multilingüe muestra variación interesante: el español emplea poco, el francés modérément. El rango clásico incluye tamaño, tiempo o número moderados, apuntando siempre al punto medio entre los extremos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3358', 'spa', 'Medida: un patrón de cantidad, extensión o proporción; tanto el instrumento como el acto de medir. Μέτρον es la palabra griega para cualquier patrón d', 'Medida: un patrón de cantidad, extensión o proporción; tanto el instrumento como el acto de medir. Μέτρον es la palabra griega para cualquier patrón de medición, ya sea un recipiente para grano, una regla de longitud o un referente figurativo de proporción. Jesús la emplea en el memorable proverbio sobre la reciprocidad: ''Con la medida con que midáis, se os medirá'' (Mt 7:2; Mc 4:24; Lc 6:38). Pablo la utiliza para describir la esfera o límite divinamente asignado de autoridad apostólica (2 Co 10:13) y ''la medida del don de Cristo'' distribuida a cada creyente (Ef 4:7, 13, 16). La palabra siempre implica un patrón: no arbitrario, sino calibrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3359', 'spa', 'La frente, parte frontal de la cabeza sobre los ojos; en el NT se usa exclusivamente como sitio de marcas divinas o bestiales.', 'Derivado de meta (entre) y ops (ojo), metopon designa la frente, literalmente el espacio entre los ojos. En el Nuevo Testamento, todas sus apariciones se encuentran en Apocalipsis, donde la frente se convierte en el terreno mas disputado del drama apocaliptico: es donde los siervos de Dios reciben el sello divino (Ap 7:3, 14:1) y donde los seguidores de la bestia llevan su marca (Ap 13:16, 17:5). El espanol ''frente'' preserva el sentido anatomico directo, mientras que toda la carga teologica viene dada por el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3360', 'spa', 'Preposición y conjunción que marca el límite espacial o temporal de una acción o estado: ''hasta,'' ''hasta el punto de.'' De sus 18 apariciones en el Nue', 'Preposición y conjunción que marca el límite espacial o temporal de una acción o estado: ''hasta,'' ''hasta el punto de.'' De sus 18 apariciones en el Nuevo Testamento, predominan los usos temporales. Mateo 28:15 relata que la historia del cuerpo robado ''se ha divulgado entre los judíos hasta el día de hoy'' (μέχρι τῆς σήμερον), y Mateo 11:23 advierte que Capernaúm descenderá ''hasta el Hades'' (μέχρι ᾅδου), uno de los escasos usos espaciales. Pablo lleva la palabra a su límite teológico en Filipenses 2:8, declarando que Cristo fue obediente ''hasta la muerte'' (μέχρι θανάτου) — incluso muerte de cruz — donde μέχρι marca no un simple punto final sino un extremo culminante. Efesios 4:13 proyecta el crecimiento ''hasta que todos lleguemos a la unidad de la fe.'' Hebreos la emplea para la perseverancia temporal: luchar contra el pecado ''hasta la sangre'' (Heb 12:4) y permanecer fieles ''hasta el fin'' (Heb 3:6, 14).');